def _stage122_record318_lifecycle_next_action(
    diagnostic: dict[str, Any],
) -> str | None:
    if diagnostic.get("stage122_record318_lifecycle_write_source_found") is True:
        return (
            "validate_stage122_record318_write_source_authority_against_cpu_"
            "oracle_cuda700"
        )
    if (
        diagnostic.get("stage122_record318_lifecycle_probe_event")
        and diagnostic.get("stage122_record318_lifecycle_write_source_found") is False
    ):
        return STAGE123_POST_SUPPRESSION_CONCRETE_WRITE_WINDOW_BISECTION_ACTION
    return None


def _stage123_record318_concrete_write_window_next_action(
    diagnostic: dict[str, Any],
) -> str | None:
    event = diagnostic.get("stage123_record318_concrete_write_window_probe_event") or {}
    if (
        diagnostic.get("stage123_record318_concrete_write_window_write_source_found")
        is True
    ):
        if (
            event.get("target_in_record318_window") is False
            and event.get("target_in_adjacent_window") is True
        ):
            return (
                "validate_stage123_adjacent_window_concrete_write_source_against_"
                "cpu_oracle_cuda700"
            )
        return (
            "validate_stage123_record318_concrete_write_source_against_cpu_"
            "oracle_cuda700"
        )
    if (
        diagnostic.get("stage123_concrete_write_window_bisection_probe_requested")
        is True
    ):
        return (
            "advance_stage123_post_suppression_concrete_write_window_bisection_"
            "range_cuda700"
        )
    return None


def _stage124_record318_transition_next_action(
    diagnostic: dict[str, Any],
) -> str | None:
    if diagnostic.get("stage124_record318_transition_found") is True:
        return "validate_stage124_record318_transition_source_against_cpu_oracle_cuda700"
    if diagnostic.get("stage124_record318_transition_probe_requested") is True:
        event = diagnostic.get("stage124_record318_transition_probe_event")
        if isinstance(event, dict) and event.get("transition_complete") is False:
            return "bisect_stage124_record318_transition_probe_reachability_boundary_cuda700"
        return "advance_stage124_record318_transition_probe_range_cuda700"
    return None
