def _parse_slot_count_list(text: str | None) -> list[dict[str, int]]:
    if not text or text == "none":
        return []
    result: list[dict[str, int]] = []
    for item in text.split(","):
        if not item:
            continue
        slot_text, sep, count_text = item.partition(":")
        if not sep:
            continue
        try:
            result.append({"slot": int(slot_text), "count": int(count_text)})
        except ValueError:
            continue
    return result


def _parse_slot_value_list(
    text: str | None, value_key: str
) -> list[dict[str, int]]:
    if not text or text == "none":
        return []
    result: list[dict[str, int]] = []
    for item in text.split(","):
        if not item:
            continue
        slot_text, sep, value_text = item.partition(":")
        if not sep:
            continue
        try:
            result.append({"slot": int(slot_text), value_key: int(value_text)})
        except ValueError:
            continue
    return result


def _parse_slot_edge_value_sample_list(text: str | None) -> list[dict[str, int]]:
    if not text or text == "none":
        return []
    result: list[dict[str, int]] = []
    for item in text.split(","):
        if not item:
            continue
        parts = item.split(":")
        if len(parts) != 4:
            continue
        try:
            result.append(
                {
                    "slot": int(parts[0]),
                    "incoming_edge_index": int(parts[1]),
                    "actual_value": int(parts[2]),
                    "expected_value": int(parts[3]),
                }
            )
        except ValueError:
            continue
    return result


