def _candidate_source_status_kind(status: int) -> str:
    return {
        0: "unmapped",
        1: "type_mismatch",
        2: "encode_failed",
        3: "available",
        4: "cross_block",
        6: "instruction_cfg_map_miss",
        7: "livein_decode_failed",
        8: "liveout_decode_failed",
        9: "argument_unmapped",
        10: "other_unmapped",
        11: "synthetic_liveout_load_not_cfg_mapped",
        12: "load_not_in_compact_cluster",
        13: "instruction_not_in_compact_cluster",
        14: "instruction_parent_not_in_cfg_block_map",
        15: "compact_instruction_not_cloned",
        16: "lowered_liveout_source_clone_available",
    }.get(status, "unknown")


def _lowered_liveout_source_clone_cause_kind(cause: int) -> str:
    return {
        0: "not_lowered_liveout_source_clone",
        1: "same_mapped_value",
        2: "source_mapping_mismatch",
        3: "same_mapped_phi_clone",
        4: "phi_incoming_edge_local_value_available",
        5: "phi_incoming_edge_local_value_cross_block",
        6: "phi_incoming_edge_local_type_mismatch",
        7: "phi_incoming_edge_local_unmapped",
        8: "phi_incoming_edge_index_unavailable",
        9: "phi_incoming_edge_local_predecessor_ambiguous",
        10: "phi_incoming_edge_local_rematerialize_unsupported",
        11: "phi_incoming_edge_rematerialize_missing_input_or_target",
        12: "phi_incoming_edge_rematerialize_livein_decode_failed",
        13: "phi_incoming_edge_rematerialize_cross_block_mapped_non_instruction",
        14: "phi_incoming_edge_rematerialize_original_value_not_instruction",
        15: "phi_incoming_edge_rematerialize_original_pred_unavailable",
        16: "phi_incoming_edge_rematerialize_original_instruction_not_compact",
        17: "phi_incoming_edge_rematerialize_original_instruction_phi",
        18: "phi_incoming_edge_rematerialize_original_instruction_terminator",
        19: "phi_incoming_edge_rematerialize_original_instruction_alloca",
        20: "phi_incoming_edge_rematerialize_original_instruction_call",
        21: "phi_incoming_edge_rematerialize_original_instruction_memory",
        22: "phi_incoming_edge_rematerialize_original_instruction_side_effect",
        23: "phi_incoming_edge_rematerialize_original_instruction_not_dominating_edge",
        24: "phi_incoming_edge_rematerialize_original_instruction_not_speculatable",
        25: "phi_incoming_edge_rematerialize_recursion_cycle",
        26: "phi_incoming_edge_rematerialize_operand_basicblock",
        27: "phi_incoming_edge_rematerialize_operand_unavailable",
        28: "phi_incoming_edge_rematerialize_operand_type_mismatch",
        29: "phi_incoming_edge_memory_load_shadow_payload_record_unavailable",
        30: "phi_incoming_edge_memory_load_shadow_payload_type_mismatch",
        31: "cfg_clone_runtime_entry_dispatch_not_ready",
        32: "phi_incoming_edge_global_constant_memory_load_pointer_rematerialize_unavailable",
        33: "consumer_phi_edge_index_not_producer_phi_predecessor_mapping",
        34: "runtime_producer_phi_predecessor_selector_selected_value",
    }.get(cause, "unknown")


def _parse_slot_edge_status_sample_list(text: str | None) -> list[dict[str, Any]]:
    if not text or text == "none":
        return []
    result: list[dict[str, int]] = []
    for item in text.split(","):
        if not item:
            continue
        parts = item.split(":")
        if len(parts) != 3:
            continue
        try:
            status = int(parts[2])
            result.append(
                {
                    "slot": int(parts[0]),
                    "incoming_edge_index": int(parts[1]),
                    "status": status,
                    "status_kind": _candidate_source_status_kind(status),
                }
            )
        except ValueError:
            continue
    return result


