def _summarize_selected_phi_store_site_stable_path_mismatch_samples(
    samples: list[dict[str, int]],
    *,
    reload_samples: list[dict[str, int]] | None = None,
    encoded_before_store_reload_samples: list[dict[str, int]] | None = None,
    candidate_source_status_samples: list[dict[str, int]] | None = None,
    lowered_liveout_source_clone_cause_samples: list[dict[str, Any]] | None = None,
    producer_selector_slots: list[dict[str, int]] | None = None,
    producer_selector_last_slots: list[dict[str, int]] | None = None,
    producer_selector_read_encoded_slots: list[dict[str, int]] | None = None,
    producer_selector_selected_encoded_value_slots: list[dict[str, int]] | None = None,
    producer_selector_selected_edge_mapped_slots: list[dict[str, int]] | None = None,
    producer_selector_selected_edge_encoded_slots: list[dict[str, int]] | None = None,
    producer_selector_selected_edge_match_seen_slots: list[dict[str, int]]
    | None = None,
    producer_selector_selected_edge_map_status_slots: list[dict[str, int]]
    | None = None,
    producer_selector_selected_edge_reject_cause_slots: list[dict[str, int]]
    | None = None,
    producer_selector_materialization_phi_incoming_count_slots: list[dict[str, int]]
    | None = None,
    producer_selector_read_in_range_slots: list[dict[str, int]] | None = None,
    producer_selector_last_read_encoded_slots: list[dict[str, int]] | None = None,
    producer_selector_last_read_in_range_slots: list[dict[str, int]] | None = None,
    producer_selector_current_selector_phi_block_read_encoded_slots: list[
        dict[str, int]
    ]
    | None = None,
    producer_selector_current_selector_phi_raw_in_range_slots: list[dict[str, int]]
    | None = None,
    producer_selector_current_selector_phi_raw_selected_encoded_slots: list[
        dict[str, int]
    ]
    | None = None,
    producer_selector_current_selector_phi_raw_selector_slots: list[dict[str, int]]
    | None = None,
    producer_selector_current_selector_phi_raw_encoded_source_slots: list[
        dict[str, int]
    ]
    | None = None,
    producer_selector_post_fallback_selector_slots: list[dict[str, int]]
    | None = None,
    producer_selector_post_fallback_phi_incoming_count_slots: list[dict[str, int]]
    | None = None,
    producer_selector_post_fallback_read_in_range_slots: list[dict[str, int]]
    | None = None,
    producer_selector_post_fallback_edge_match_seen_slots: list[dict[str, int]]
    | None = None,
    producer_selector_side_probe_selector_slots: list[dict[str, int]] | None = None,
    producer_selector_side_probe_phi_incoming_count_slots: list[dict[str, int]]
    | None = None,
    producer_selector_side_probe_edge_seen_slots: list[dict[str, int]] | None = None,
    producer_selector_side_probe_slot_token_slots: list[dict[str, int]] | None = None,
    producer_selector_selected_edge_mapped_value_kind_slots: list[dict[str, int]]
    | None = None,
    producer_selector_selected_edge_original_value_kind_slots: list[dict[str, int]]
    | None = None,
    producer_selector_selected_edge_encode_eligible_slots: list[dict[str, int]]
    | None = None,
    producer_selector_selected_edge_mapped_opcode_slots: list[dict[str, int]]
    | None = None,
    store_before_value_sample_survival_summary: dict[str, Any] | None = None,
    producer_selected_encoded_value_sample_survival_summary: dict[str, Any]
    | None = None,
) -> dict[str, Any] | None:
    if encoded_before_store_reload_samples:
        status_by_slot = {
            (sample["slot"], sample["incoming_edge_index"]): sample["status"]
            for sample in candidate_source_status_samples or []
        }
        def _sample_status(sample: dict[str, int]) -> int:
            return status_by_slot.get(
                (sample["slot"], sample["incoming_edge_index"]), 0
            )
        cause_by_slot = {
            (sample["slot"], sample["incoming_edge_index"]): sample["cause"]
            for sample in lowered_liveout_source_clone_cause_samples or []
        }
        def _source_clone_cause(sample: dict[str, int]) -> int:
            return cause_by_slot.get(
                (sample["slot"], sample["incoming_edge_index"]), 0
            )
        available_statuses = {3, 16}

        encoded_before_store_zero = [
            sample
            for sample in encoded_before_store_reload_samples
            if sample["encoded_before_store"] == 0
            and sample["reloaded_value"] == 0
            and sample["actual_value"] != 0
            and sample["expected_value"] != 0
            and sample["actual_value"] != sample["expected_value"]
        ]
        encoded_before_store_bridge_nonzero_semantic_mismatch = [
            sample
            for sample in encoded_before_store_reload_samples
            if sample["candidate_source_value"] != 0
            and sample["candidate_source_value"] == sample["encoded_before_store"]
            and sample["encoded_before_store"] == sample["reloaded_value"]
            and sample["encoded_before_store"] != sample["actual_value"]
            and sample["encoded_before_store"] != sample["expected_value"]
            and sample["actual_value"] != sample["expected_value"]
        ]
        encoded_before_store_bridge_matches_actual_expected_mismatch = [
            sample
            for sample in encoded_before_store_reload_samples
            if sample["candidate_source_value"] != 0
            and sample["candidate_source_value"] == sample["encoded_before_store"]
            and sample["encoded_before_store"] == sample["reloaded_value"]
            and sample["encoded_before_store"] == sample["actual_value"]
            and sample["actual_value"] != sample["expected_value"]
        ]
        encoded_before_store_bridge_matches_expected_actual_mismatch = [
            sample
            for sample in encoded_before_store_reload_samples
            if sample["candidate_source_value"] != 0
            and sample["candidate_source_value"] == sample["encoded_before_store"]
            and sample["encoded_before_store"] == sample["reloaded_value"]
            and sample["encoded_before_store"] == sample["expected_value"]
            and sample["actual_value"] != sample["expected_value"]
        ]
        candidate_available_zero = [
            sample
            for sample in encoded_before_store_zero
            if _sample_status(sample) in available_statuses
            and sample["candidate_source_value"] == 0
        ]
        candidate_available_nonzero = [
            sample
            for sample in encoded_before_store_zero
            if _sample_status(sample) in available_statuses
            and sample["candidate_source_value"] != 0
        ]
        candidate_unavailable = [
            sample
            for sample in encoded_before_store_zero
            if _sample_status(sample) not in available_statuses
        ]
        candidate_lowered_liveout_source_clone_available_zero = [
            sample
            for sample in encoded_before_store_zero
            if _sample_status(sample) == 16
            and sample["candidate_source_value"] == 0
        ]
        candidate_lowered_liveout_source_clone_same_mapped_value_zero = [
            sample
            for sample in candidate_lowered_liveout_source_clone_available_zero
            if _source_clone_cause(sample) == 1
        ]
        candidate_lowered_liveout_source_clone_source_mapping_mismatch_zero = [
            sample
            for sample in candidate_lowered_liveout_source_clone_available_zero
            if _source_clone_cause(sample) == 2
        ]
        candidate_lowered_liveout_source_clone_same_mapped_phi_clone_zero = [
            sample
            for sample in candidate_lowered_liveout_source_clone_available_zero
            if _source_clone_cause(sample) == 3
        ]
        candidate_lowered_liveout_source_clone_phi_edge_available_zero = [
            sample
            for sample in candidate_lowered_liveout_source_clone_available_zero
            if _source_clone_cause(sample) == 4
        ]
        candidate_lowered_liveout_source_clone_phi_edge_cross_block_zero = [
            sample
            for sample in candidate_lowered_liveout_source_clone_available_zero
            if _source_clone_cause(sample) == 5
        ]
        candidate_lowered_liveout_source_clone_phi_edge_type_mismatch_zero = [
            sample
            for sample in candidate_lowered_liveout_source_clone_available_zero
            if _source_clone_cause(sample) == 6
        ]
