def _parse_partition_local_refactor_shapes(ir_text: str) -> list[dict[str, Any]]:
    named = re.search(
        r"!vlgpu\.eval_hot_path_partition_local_refactor_shapes\s*=\s*!\{(?P<body>[^}]*)\}",
        ir_text,
    )
    if not named:
        return []

    shape_node_ids = {
        match.group("node_id") for match in LLVM_METADATA_NODE_ID_RE.finditer(named.group("body"))
    }
    if not shape_node_ids:
        return []

    node_bodies = {
        match.group("node_id"): match.group("body")
        for match in LLVM_METADATA_NODE_DEF_RE.finditer(ir_text)
    }
    shapes: dict[tuple[str, str], int] = {}
    for node_id in shape_node_ids:
        body = node_bodies.get(node_id)
        if not body:
            continue
        shape_match = LLVM_PARTITION_LOCAL_REFACTOR_SHAPE_RE.search(body)
        if not shape_match:
            continue
        key = (shape_match.group("refactor"), shape_match.group("shape"))
        shapes[key] = shapes.get(key, 0) + int(shape_match.group("count"))
    return [
        {"refactor": refactor, "shape": shape, "count": count}
        for (refactor, shape), count in sorted(
            shapes.items(), key=lambda item: (-item[1], item[0][0], item[0][1])
        )
    ]


