            "candidate_cluster_count",
            "outline_cluster_block_count",
            "cluster_instruction_count",
            "explicit_livein_value_count",
            "explicit_liveout_value_count",
            "external_liveout_user_count",
            "phi_liveout_value_count",
            "unsupported_external_liveout_user_count",
            "existing_wrapper_abi_compatible",
            "lowered_livein_frame_value_count",
            "lowered_livein_frame_store_count",
            "unsupported_livein_frame_value_count",
            "livein_frame_phi_incoming_store_count",
            "livein_frame_non_phi_store_count",
            "lowered_liveout_frame_value_count",
            "lowered_liveout_frame_store_count",
            "unsupported_liveout_frame_value_count",
