def _parse_repaired_select_only_compact_cluster_selected_phi_incoming_materialization_summary(
    ir_text: str,
) -> dict[str, Any] | None:
    named = re.search(
        r"!vlgpu\.eval_hot_path_repaired_select_only_compact_cluster_selected_phi_incoming_materialization_summary\s*=\s*!\{(?P<body>[^}]*)\}",
        ir_text,
    )
    if not named:
        return None

    summary_node_ids = [
        match.group("node_id")
        for match in LLVM_METADATA_NODE_ID_RE.finditer(named.group("body"))
    ]
    if not summary_node_ids:
        return None

    node_bodies = {
        match.group("node_id"): match.group("body")
        for match in LLVM_METADATA_NODE_DEF_RE.finditer(ir_text)
    }
    summaries = []
    for node_id in summary_node_ids:
        body = node_bodies.get(node_id)
        if not body:
            continue
        summary_match = (
            LLVM_REPAIRED_SELECT_ONLY_COMPACT_CLUSTER_SELECTED_PHI_INCOMING_MATERIALIZATION_SUMMARY_RE.search(
                body
            )
        )
        if not summary_match:
            continue
        int_fields = (
            "reviewed_candidate_count",
            "selected_phi_incoming_materialized_count",
            "runtime_edge_selector_count",
            "missing_runtime_edge_selector_count",
            "expected_frame_shortcut_rejected_count",
            "blocked_count",
        )
        summaries.append(
            {
                "status": summary_match.group("status"),
                **{field: int(summary_match.group(field)) for field in int_fields},
                "next_action": summary_match.group("next_action"),
                "authority": summary_match.group("authority"),
            }
        )
    if not summaries:
        return None
    return max(
        summaries,
        key=lambda summary: (
            summary["reviewed_candidate_count"],
            summary["blocked_count"],
        ),
    )


def _parse_repaired_select_only_compact_cluster_selected_phi_incoming_materialization_failure_summary(
    ir_text: str,
) -> dict[str, Any] | None:
    named = re.search(
        r"!vlgpu\.eval_hot_path_repaired_select_only_compact_cluster_selected_phi_incoming_materialization_failure_summary\s*=\s*!\{(?P<body>[^}]*)\}",
        ir_text,
    )
    if not named:
        return None

    summary_node_ids = [
        match.group("node_id")
        for match in LLVM_METADATA_NODE_ID_RE.finditer(named.group("body"))
    ]
    if not summary_node_ids:
        return None

    node_bodies = {
        match.group("node_id"): match.group("body")
        for match in LLVM_METADATA_NODE_DEF_RE.finditer(ir_text)
    }
    summaries = []
    for node_id in summary_node_ids:
        body = node_bodies.get(node_id)
        if not body:
            continue
        summary_match = (
            LLVM_REPAIRED_SELECT_ONLY_COMPACT_CLUSTER_SELECTED_PHI_INCOMING_MATERIALIZATION_FAILURE_SUMMARY_RE.search(
                body
            )
        )
        if not summary_match:
            continue
        int_fields = (
            "visited_candidate_count",
            "materialized_count",
            "invalid_candidate_count",
            "missing_slot_count",
            "slot_out_of_range_count",
            "missing_cfg_block_count",
            "unmapped_value_count",
            "type_mismatch_count",
            "encode_failed_count",
            "frame_missing_count",
        )
        summaries.append(
            {
                "status": summary_match.group("status"),
                **{field: int(summary_match.group(field)) for field in int_fields},
                "materialized_slots": _parse_slot_id_list(
                    summary_match.group("materialized_slots")
                ),
                "missing_cfg_block_slots": _parse_slot_id_list(
                    summary_match.group("missing_cfg_block_slots")
                ),
                "unmapped_value_slots": _parse_slot_id_list(
                    summary_match.group("unmapped_value_slots")
                ),
                "type_mismatch_slots": _parse_slot_id_list(
                    summary_match.group("type_mismatch_slots")
                ),
                "encode_failed_slots": _parse_slot_id_list(
                    summary_match.group("encode_failed_slots")
                ),
                "frame_missing_slots": _parse_slot_id_list(
                    summary_match.group("frame_missing_slots")
                ),
                "next_action": summary_match.group("next_action"),
                "authority": summary_match.group("authority"),
            }
        )
    if not summaries:
        return None
    return max(
        summaries,
        key=lambda summary: (
            summary["visited_candidate_count"],
            summary["unmapped_value_count"],
            summary["materialized_count"],
        ),
    )


def _selected_phi_store_site_path_markers_from_ir(ir_text: str) -> dict[str, bool]:
    stable_return_path_compare_present = (
        "entry_phi_selected_incoming_value_store_site_compare_moved_to_stable_return_path_no_actual_valid_authority"
        in ir_text
        or "entry_phi_selected_incoming_value_store_site_compare_stable_return_path_runtime_counter"
        in ir_text
        or "selected_value.store_compare.stable_return_path.slot_counter"
        in ir_text
    )
    stable_return_path_mismatch_present = (
        "entry_phi_selected_incoming_value_store_site_mismatch_moved_to_stable_return_path_no_actual_valid_authority"
        in ir_text
        or "entry_phi_selected_incoming_value_store_site_mismatch_stable_return_path_runtime_counter"
        in ir_text
        or "selected_value.store_mismatch.stable_return_path.slot_counter"
        in ir_text
    )
    true_store_site_compare_present = (
        "entry_phi_selected_incoming_value_store_site_compared_against_expected_liveout_expected_valid_gated_no_actual_valid_authority"
        in ir_text
        or "entry_phi_selected_incoming_value_store_site_compare_runtime_counter"
        in ir_text
        or "selected_value.store_compare.slot_counter" in ir_text
    )
    true_store_site_mismatch_present = (
        "entry_phi_selected_incoming_value_store_site_mismatch_against_expected_liveout_expected_valid_gated_no_actual_valid_authority"
        in ir_text
        or "entry_phi_selected_incoming_value_store_site_mismatch_runtime_counter"
        in ir_text
        or "selected_value.store_mismatch.slot_counter" in ir_text
    )
    true_store_site_expected_valid_present = (
        "entry_phi_selected_incoming_value_store_site_expected_valid_observed_no_actual_valid_authority"
        in ir_text
        or "entry_phi_selected_incoming_value_store_site_expected_valid_runtime_counter"
        in ir_text
        or "selected_value.store_expected_valid.slot_counter" in ir_text
    )
    true_store_site_expected_valid_missing_present = (
        "entry_phi_selected_incoming_value_store_site_expected_valid_missing_at_selected_value_store_no_actual_valid_authority"
        in ir_text
    )
    true_store_site_reached_present = (
        "entry_phi_selected_incoming_value_store_site_reached_no_actual_valid_authority"
        in ir_text
        or "entry_phi_selected_incoming_value_store_site_reached_runtime_counter"
        in ir_text
        or "entry_phi_selected_incoming_value_store_site_reached_fail_closed_dispatch_not_ready_no_actual_valid_authority"
        in ir_text
    )
    return {
        "return_compare_proxy_present": (
            "store_site_reached.return_compare_proxy" in ir_text
            or "entry_phi_selected_incoming_value_store_site_reached_unproven_return_compare_proxy_no_actual_valid_authority"
            in ir_text
        ),
        "return_compare_expected_valid_missing_present": (
            "entry_phi_selected_incoming_value_store_site_expected_valid_unproven_at_selected_value_return_compare_no_actual_valid_authority"
            in ir_text
        ),
        "stable_return_path_store_site_compare_counter_present": stable_return_path_compare_present,
        "stable_return_path_store_site_mismatch_counter_present": stable_return_path_mismatch_present,
        "true_store_site_reached_counter_present": true_store_site_reached_present,
        "true_store_site_compare_counter_present": true_store_site_compare_present,
        "true_store_site_mismatch_counter_present": true_store_site_mismatch_present,
        "true_store_site_expected_valid_counter_present": true_store_site_expected_valid_present,
        "true_store_site_expected_valid_missing_at_store_counter_present": true_store_site_expected_valid_missing_present,
        "true_store_site_any_counter_present": any(
            (
                true_store_site_reached_present,
                true_store_site_compare_present,
                true_store_site_mismatch_present,
                true_store_site_expected_valid_present,
                true_store_site_expected_valid_missing_present,
            )
        ),
    }


def _summarize_selected_phi_store_site_path_elision_from_opt_ir(
    ir_text: str,
    *,
    source_ir_text: str | None = None,
) -> dict[str, Any]:
    optimized_markers = _selected_phi_store_site_path_markers_from_ir(ir_text)
    source_markers = (
        _selected_phi_store_site_path_markers_from_ir(source_ir_text)
        if source_ir_text is not None
        else None
    )
    return_compare_proxy_present = optimized_markers["return_compare_proxy_present"]
    true_store_site_any_present = optimized_markers[
        "true_store_site_any_counter_present"
    ]
    source_true_store_site_any_present = (
        source_markers["true_store_site_any_counter_present"]
        if isinstance(source_markers, dict)
        else None
    )
    if (
        return_compare_proxy_present
        and optimized_markers["stable_return_path_store_site_compare_counter_present"]
    ):
        status = "store_site_compare_moved_to_stable_return_path_return_compare_proxy_retained"
        next_action = (
            "rerun_bounded_selector_smoke_to_classify_stable_path_store_site_compare_mismatch_before_actual_valid"
        )
    elif (
        return_compare_proxy_present
        and source_true_store_site_any_present is True
        and not true_store_site_any_present
    ):
        status = "true_store_site_path_generated_then_elided_by_gpu_opt_return_compare_proxy_retained"
        next_action = (
            "preserve_true_store_site_survival_counter_through_gpu_opt_or_move_compare_to_stable_path_before_actual_valid"
        )
    elif return_compare_proxy_present and not true_store_site_any_present:
        status = "true_store_site_path_elided_return_compare_proxy_retained"
        next_action = (
            "classify_selected_phi_incoming_value_store_site_path_elided_after_return_compare_proxy_before_actual_valid"
        )
    elif (
        optimized_markers["true_store_site_compare_counter_present"]
        or optimized_markers["true_store_site_expected_valid_counter_present"]
    ):
        status = "true_store_site_compare_or_expected_valid_retained"
        next_action = (
            "review_selected_phi_incoming_value_store_site_immediate_compare_before_actual_valid_authority"
        )
    elif return_compare_proxy_present:
        status = "return_compare_proxy_retained_true_store_site_path_partially_unclassified"
        next_action = (
            "classify_selected_phi_incoming_value_store_site_path_elided_after_return_compare_proxy_before_actual_valid"
        )
    elif true_store_site_any_present:
        status = "true_store_site_reached_retained_without_compare"
        next_action = (
            "wire_cfg_clone_runtime_entry_dispatch_before_selected_phi_store_site_compare"
        )
    else:
        status = "store_site_path_and_return_compare_proxy_not_found_in_optimized_ir"
        next_action = (
            "preserve_selected_phi_incoming_value_store_site_reached_counter_through_gpu_opt_before_store_site_compare"
        )
    return {
        "status": status,
        "authority": (
            "source_and_optimized_ir_store_site_path_classification_no_actual_valid_authority"
            if source_ir_text is not None
            else "optimized_ir_store_site_path_classification_no_actual_valid_authority"
        ),
        "return_compare_proxy_present": return_compare_proxy_present,
        "return_compare_expected_valid_missing_present": optimized_markers[
            "return_compare_expected_valid_missing_present"
        ],
        "stable_return_path_store_site_compare_counter_present": optimized_markers[
            "stable_return_path_store_site_compare_counter_present"
        ],
        "stable_return_path_store_site_mismatch_counter_present": optimized_markers[
            "stable_return_path_store_site_mismatch_counter_present"
        ],
        "true_store_site_any_counter_present": true_store_site_any_present,
        "true_store_site_reached_counter_present": optimized_markers[
            "true_store_site_reached_counter_present"
        ],
        "true_store_site_compare_counter_present": optimized_markers[
            "true_store_site_compare_counter_present"
        ],
        "true_store_site_mismatch_counter_present": optimized_markers[
            "true_store_site_mismatch_counter_present"
        ],
        "true_store_site_expected_valid_counter_present": optimized_markers[
            "true_store_site_expected_valid_counter_present"
        ],
        "true_store_site_expected_valid_missing_at_store_counter_present": optimized_markers[
            "true_store_site_expected_valid_missing_at_store_counter_present"
        ],
        "source_true_store_site_any_counter_present": source_true_store_site_any_present,
        "source_true_store_site_reached_counter_present": (
            source_markers["true_store_site_reached_counter_present"]
            if isinstance(source_markers, dict)
            else None
        ),
        "source_true_store_site_compare_counter_present": (
            source_markers["true_store_site_compare_counter_present"]
            if isinstance(source_markers, dict)
            else None
        ),
        "source_true_store_site_expected_valid_counter_present": (
            source_markers["true_store_site_expected_valid_counter_present"]
            if isinstance(source_markers, dict)
            else None
        ),
        "source_stable_return_path_store_site_compare_counter_present": (
            source_markers["stable_return_path_store_site_compare_counter_present"]
            if isinstance(source_markers, dict)
            else None
        ),
        "actual_valid_authority_claimed": False,
        "next_action": next_action,
    }


def _summarize_selected_phi_store_before_value_sample_survival_from_ir(
    ir_text: str,
    *,
    source_ir_text: str | None = None,
) -> dict[str, Any]:
    sample_markers = {
        "candidate_source_value": "compact.cfg_clone.entry_phi.selected_value.candidate_source.value.sample",
        "materialized_store": "compact.cfg_clone.entry_phi.selected_value.materialized_store.sample",
        "materialized_store_reload": "compact.cfg_clone.entry_phi.selected_value.materialized_store.reload.sample",
    }

    def _counts(text: str | None) -> dict[str, int] | None:
        if text is None:
            return None
        return {name: text.count(marker) for name, marker in sample_markers.items()}

    optimized_counts = _counts(ir_text) or {}
    source_counts = _counts(source_ir_text)
    optimized_present = any(count > 0 for count in optimized_counts.values())
    source_present = (
        any(count > 0 for count in source_counts.values())
        if source_counts is not None
        else None
    )
    return {
        "status": (
            "store_before_value_samples_generated_then_elided_by_gpu_opt"
            if source_present is True and not optimized_present
            else "store_before_value_samples_retained_in_optimized_ir"
            if optimized_present
            else "store_before_value_samples_not_found_in_ir"
        ),
        "authority": (
            "source_and_optimized_ir_value_sample_survival_no_actual_valid_authority"
            if source_ir_text is not None
            else "optimized_ir_value_sample_survival_no_actual_valid_authority"
        ),
        "source_value_sample_present": source_present,
        "optimized_value_sample_present": optimized_present,
        "source_sample_counts": source_counts,
        "optimized_sample_counts": optimized_counts,
        "actual_valid_authority_claimed": False,
    }


