def _summarize_selected_phi_candidate_source_status_samples_from_ir(
    ir_text: str,
) -> dict[str, Any]:
    status_counts: dict[int, int] = {}
    for line in ir_text.splitlines():
        if (
            "entry_phi_selected_incoming_value_candidate_source_status_sample"
            not in line
            and "candidate_source.status.sample" not in line
        ):
            continue
        match = re.search(r"atomicrmw\s+volatile\s+xchg\b.*\bi64\s+(\d+)\b", line)
        if not match:
            continue
        status = int(match.group(1))
        status_counts[status] = status_counts.get(status, 0) + 1
    dominant_status = None
    if status_counts:
        dominant_status = max(status_counts.items(), key=lambda item: item[1])[0]
    return {
        "present": bool(status_counts),
        "sample_count": sum(status_counts.values()),
        "status_counts": {
            str(status): count for status, count in sorted(status_counts.items())
        },
        "dominant_status": dominant_status,
        "dominant_status_kind": (
            _candidate_source_status_kind(dominant_status)
            if dominant_status is not None
            else None
        ),
        "authority": "ir_marker_presence_only_no_actual_valid_authority",
    }


def _stage117_block_body_boundary_control_word(source_id: int) -> int:
    return source_id | (2 << 32) | (1 << 40) | (1 << 56)


def _line_number_for_offset(text: str, offset: int) -> int:
    return text.count("\n", 0, offset) + 1


def _find_llvm_function_before(lines: list[str], line_index: int) -> str | None:
    for index in range(line_index, -1, -1):
        match = LLVM_FUNCTION_DEF_RE.match(lines[index])
        if match:
            return match.group("function")
    return None


def _find_llvm_block_label_before(
    lines: list[str],
    line_index: int,
) -> tuple[str | None, int | None]:
    for index in range(line_index, -1, -1):
        if LLVM_FUNCTION_DEF_RE.match(lines[index]):
            return None, None
        match = LLVM_BASIC_BLOCK_LABEL_RE.match(lines[index])
        if match:
            return match.group("label"), index + 1
    return None, None


def _find_first_stage117_probe_line_in_block(
    lines: list[str],
    *,
    block_start_line: int | None,
    control_word_line: int | None,
) -> int | None:
    if block_start_line is None or control_word_line is None:
        return None
    start_index = max(block_start_line - 1, 0)
    end_index = min(control_word_line, len(lines))
    for index in range(start_index, end_index):
        if "stage117.callee0_nested_body_block_body_boundary" in lines[index]:
            return index + 1
    return None


def _summarize_stage117_block_body_boundary_source_ir_mapping_from_ir(
    ir_text: str | None,
    source_id: int | None,
) -> dict[str, Any] | None:
    if source_id is None:
        return None
    if ir_text is None:
        return {
            "present": False,
            "source_id": source_id,
            "mapping_status": "stage117_source_ir_missing",
            "authority": "ir_mapping_unavailable_no_runtime_or_semantic_authority",
        }

    matching_row: dict[str, Any] | None = None
    for match in LLVM_STAGE117_BLOCK_BODY_BOUNDARY_MAP_ROW_RE.finditer(ir_text):
        if int(match.group("source_id")) != source_id:
            continue
        matching_row = {
            "metadata_row_line": _line_number_for_offset(ir_text, match.start()),
            "metadata_function": match.group("function"),
            "metadata_boundary_kind_id": int(match.group("boundary_kind_id")),
            "metadata_block_name": match.group("block_name"),
        }
        break

    control_word = _stage117_block_body_boundary_control_word(source_id)
    control_word_text = f"i64 {control_word}"
    lines = ir_text.splitlines()
    expected_function = (
        matching_row.get("metadata_function") if matching_row is not None else None
    )
    control_word_line = None
    control_word_function = None
    block_label = None
    block_start_line = None
    for index, line in enumerate(lines):
        if control_word_text not in line:
            continue
        function = _find_llvm_function_before(lines, index)
        if expected_function is not None and function != expected_function:
            continue
        control_word_line = index + 1
        control_word_function = function
        block_label, block_start_line = _find_llvm_block_label_before(lines, index)
        break

    first_probe_line = _find_first_stage117_probe_line_in_block(
        lines,
        block_start_line=block_start_line,
        control_word_line=control_word_line,
    )
    present = matching_row is not None or control_word_line is not None
    mapping_status = (
        "stage117_source_id_ir_mapping_present"
        if matching_row is not None and control_word_line is not None
        else "stage117_source_id_metadata_only"
        if matching_row is not None
        else "stage117_source_id_control_word_site_only"
        if control_word_line is not None
        else "stage117_source_id_ir_mapping_absent"
    )
    return {
        "present": present,
        "source_id": source_id,
        "control_word": control_word,
        "mapping_status": mapping_status,
        "metadata_row_line": (
            matching_row.get("metadata_row_line") if matching_row is not None else None
        ),
        "metadata_function": (
            matching_row.get("metadata_function") if matching_row is not None else None
        ),
        "metadata_boundary_kind_id": (
            matching_row.get("metadata_boundary_kind_id")
            if matching_row is not None
            else None
        ),
        "metadata_block_name": (
            matching_row.get("metadata_block_name") if matching_row is not None else None
        ),
        "control_word_line": control_word_line,
        "control_word_function": control_word_function,
        "llvm_block_label": block_label,
        "llvm_block_start_line": block_start_line,
        "first_stage117_probe_line_in_block": first_probe_line,
        "source_line_status": "unavailable_no_debug_locations",
        "authority": "diagnostic_ir_mapping_only_no_write_source_or_semantic_authority",
    }


def _summarize_stage118_block_instruction_boundary_source_ir_mapping_from_ir(
    ir_text: str | None,
    *,
    block_source_id: int | None,
    source_id: int | None,
) -> dict[str, Any] | None:
    if block_source_id is None or source_id is None:
        return None
    if ir_text is None:
        return {
            "present": False,
            "block_source_id": block_source_id,
            "source_id": source_id,
            "mapping_status": "stage118_source_ir_missing",
            "authority": "ir_mapping_unavailable_no_runtime_or_semantic_authority",
        }

    matching_row: dict[str, Any] | None = None
    for match in LLVM_STAGE118_BLOCK_INSTRUCTION_BOUNDARY_MAP_ROW_RE.finditer(
        ir_text
    ):
        if int(match.group("block_source_id")) != block_source_id:
            continue
        if int(match.group("source_id")) != source_id:
            continue
        matching_row = {
            "metadata_row_line": _line_number_for_offset(ir_text, match.start()),
            "metadata_function": match.group("function"),
            "metadata_boundary_kind_id": int(match.group("boundary_kind_id")),
            "metadata_block_name": match.group("block_name"),
            "metadata_opcode": match.group("opcode"),
            "metadata_instruction_name": match.group("instruction_name"),
        }
        break

    lines = ir_text.splitlines()
    control_word_line = None
    control_word_function = None
    llvm_block_label = None
    llvm_block_start_line = None
    for index, line in enumerate(lines):
        if (
            "stage118.callee0_nested_body_block_instruction_boundary.control_word"
            not in line
            or f"or i64 {source_id}," not in line
        ):
            continue
        function = _find_llvm_function_before(lines, index)
        expected_function = (
            matching_row.get("metadata_function") if matching_row is not None else None
        )
        if expected_function is not None and function != expected_function:
            continue
        control_word_line = index + 1
        control_word_function = function
        llvm_block_label, llvm_block_start_line = _find_llvm_block_label_before(
            lines,
            index,
        )
        break

    instruction_line = None
    instruction_text = None
    if control_word_line is not None:
        control_index = control_word_line - 1
        before_record_line_index = None
        for index in range(control_index, -1, -1):
            line = lines[index]
            if re.match(r"^\s*[A-Za-z0-9_$.\-]+:", line) or LLVM_FUNCTION_DEF_RE.match(
                line
            ):
                break
            if (
                "stage118.callee0_nested_body_block_instruction_boundary.before.record318.offset"
                in line
            ):
                before_record_line_index = index
                break
        if before_record_line_index is not None:
            for index in range(before_record_line_index + 1, control_index):
                stripped = lines[index].strip()
                if not stripped or "stage118.callee0_nested_body_block_instruction_boundary" in stripped:
                    continue
                instruction_line = index + 1
                instruction_text = stripped
                break

    present = matching_row is not None or instruction_line is not None
    mapping_status = (
        "stage118_source_id_ir_mapping_present"
        if matching_row is not None and instruction_line is not None
        else "stage118_source_id_metadata_only"
        if matching_row is not None
        else "stage118_source_id_instruction_site_only"
        if instruction_line is not None
        else "stage118_source_id_ir_mapping_absent"
    )
    return {
        "present": present,
        "block_source_id": block_source_id,
        "source_id": source_id,
        "mapping_status": mapping_status,
        "metadata_row_line": (
            matching_row.get("metadata_row_line") if matching_row is not None else None
        ),
        "metadata_function": (
            matching_row.get("metadata_function") if matching_row is not None else None
        ),
        "metadata_boundary_kind_id": (
            matching_row.get("metadata_boundary_kind_id")
            if matching_row is not None
            else None
        ),
        "metadata_block_name": (
            matching_row.get("metadata_block_name") if matching_row is not None else None
        ),
        "metadata_opcode": (
            matching_row.get("metadata_opcode") if matching_row is not None else None
        ),
        "metadata_instruction_name": (
            matching_row.get("metadata_instruction_name")
            if matching_row is not None
            else None
        ),
        "control_word_line": control_word_line,
        "control_word_function": control_word_function,
        "llvm_block_label": llvm_block_label,
        "llvm_block_start_line": llvm_block_start_line,
        "instruction_line": instruction_line,
        "instruction_text": instruction_text,
        "source_line_status": "unavailable_no_debug_locations",
        "authority": "diagnostic_ir_mapping_only_no_write_source_or_semantic_authority",
    }


