def _summarize_stage118_block_instruction_boundary_range_summary_from_ir(
    ir_text: str | None,
) -> dict[str, Any] | None:
    if ir_text is None:
        return None

    summaries: list[dict[str, Any]] = []
    for match in LLVM_STAGE118_BLOCK_INSTRUCTION_BOUNDARY_SUMMARY_RE.finditer(
        ir_text
    ):
        candidate_count = int(match.group("candidate_count"))
        selected_count = int(match.group("selected_count"))
        range_start = int(match.group("range_start"))
        range_count = int(match.group("range_count"))
        instrumented_count = int(match.group("instrumented_count"))
        range_end_exclusive = range_start + range_count
        max_source_id = candidate_count if candidate_count > 0 else None
        range_exhausted = (
            candidate_count > 0
            and selected_count == 0
            and instrumented_count == 0
            and range_start > candidate_count
        )
        summaries.append(
            {
                "status": (
                    "stage118_block_instruction_boundary_range_exhausted"
                    if range_exhausted
                    else "stage118_block_instruction_boundary_range_summary_present"
                ),
                "summary_row_line": _line_number_for_offset(
                    ir_text,
                    match.start(),
                ),
                "function": match.group("function"),
                "block_source_id": int(match.group("block_source_id")),
                "candidate_count": candidate_count,
                "max_source_id": max_source_id,
                "selected_count": selected_count,
                "range_start": range_start,
                "range_count": range_count,
                "range_end_exclusive": range_end_exclusive,
                "range_end_inclusive": (
                    range_end_exclusive - 1 if range_count > 0 else None
                ),
                "instrumented_count": instrumented_count,
                "range_exhausted": range_exhausted,
                "range_partially_beyond_candidate_count": (
                    candidate_count > 0
                    and range_start <= candidate_count < range_end_exclusive
                ),
                "boundary_kind": match.group("boundary_kind"),
                "authority": match.group("authority"),
            }
        )

    if not summaries:
        return None
    return summaries[-1]


