def _summarize_stage114_non_store_effect_candidates_from_ir(
    ir_text: str | None,
) -> dict[str, Any] | None:
    if ir_text is None:
        return None
    summary_line = None
    census_line = None
    map_lines: list[str] = []
    for line in ir_text.splitlines():
        if (
            "high_eval_callee0_nested_call_body_non_store_memory_effect_pair_offset_watchpoint"
            in line
        ):
            if "atomic_cmpxchg_and_llvm_memory_intrinsics_only" in line:
                summary_line = line
        if "high_eval_callee0_nested_body_non_store_memory_effect_watchpoint" in line:
            map_lines.append(line)
        if (
            "high_eval_callee0_nested_call_body_non_store_memory_effect_pair_offset_candidate_census"
            in line
        ):
            census_line = line
    if census_line is None and summary_line is None and not map_lines:
        return {
            "present": False,
            "authority": "ir_metadata_presence_only_no_runtime_or_semantic_authority",
        }

    source_line = census_line or summary_line or ""
    ints = [int(value) for value in re.findall(r"\bi64\s+(\d+)\b", source_line)]
    fields = (
        [
            "total_candidates",
            "instrumented",
            "range_start",
            "range_count",
            "range_end_inclusive",
            "atomicrmw_candidate_count",
            "cmpxchg_candidate_count",
            "memory_intrinsic_candidate_count",
            "diagnostic_origin_candidate_count",
            "design_origin_candidate_count",
            "first_design_origin_source_id",
            "recommended_source_id_start",
            "recommended_source_id_count",
            "recommended_source_id_end_inclusive",
        ]
        if census_line is not None
        else [
            "total_candidates",
            "instrumented",
            "range_start",
            "range_count",
            "atomicrmw_candidate_count",
            "cmpxchg_candidate_count",
            "memory_intrinsic_candidate_count",
            "diagnostic_origin_candidate_count",
            "design_origin_candidate_count",
            "first_design_origin_source_id",
            "recommended_source_id_start",
            "recommended_source_id_count",
        ]
    )
    parsed = {name: ints[index] for index, name in enumerate(fields) if index < len(ints)}

    selected_diagnostic = 0
    selected_design = 0
    selected_source_ids: list[int] = []
    for line in map_lines:
        map_ints = [int(value) for value in re.findall(r"\bi64\s+(\d+)\b", line)]
        if map_ints:
            selected_source_ids.append(map_ints[0])
        line_is_diagnostic = any(
            marker in line
            for marker in (
                "compact.cfg_clone",
                "vlgpu.",
                "progress_",
                "candidate_source",
                "return_compare_proxy",
                "actual_valid",
            )
        )
        if line_is_diagnostic:
            selected_diagnostic += 1
        else:
            selected_design += 1

    if selected_source_ids:
        parsed["selected_source_id_min"] = min(selected_source_ids)
        parsed["selected_source_id_max"] = max(selected_source_ids)
    parsed.update(
        {
            "present": True,
            "selected_metadata_count": len(map_lines),
            "selected_diagnostic_origin_count": selected_diagnostic,
            "selected_design_origin_count": selected_design,
            "diagnostic_origin_dominates": (
                isinstance(parsed.get("diagnostic_origin_candidate_count"), int)
                and isinstance(parsed.get("total_candidates"), int)
                and parsed["total_candidates"] > 0
                and parsed["diagnostic_origin_candidate_count"]
                > parsed["total_candidates"] // 2
            ),
            "next_action": "inspect_stage114_remaining_diagnostic_origin_atomics_or_residual_cyclecond_phi_cuda700",
            "authority": "ir_metadata_presence_only_no_runtime_or_semantic_authority",
        }
    )
    return parsed


def _parse_repaired_select_only_compact_cluster_cfg_clone_liveout_compare_summary(
    ir_text: str,
) -> dict[str, Any] | None:
    named = re.search(
        r"!vlgpu\.eval_hot_path_repaired_select_only_compact_cluster_cfg_clone_liveout_compare_summary\s*=\s*!\{(?P<body>[^}]*)\}",
        ir_text,
    )
    if not named:
        return None

    summary_node_ids = [
        match.group("node_id")
        for match in LLVM_METADATA_NODE_ID_RE.finditer(named.group("body"))
    ]
    if not summary_node_ids:
        return None

    node_bodies = {
        match.group("node_id"): match.group("body")
        for match in LLVM_METADATA_NODE_DEF_RE.finditer(ir_text)
    }
    summaries = []
    for node_id in summary_node_ids:
        body = node_bodies.get(node_id)
        if not body:
            continue
        summary_match = (
            LLVM_REPAIRED_SELECT_ONLY_COMPACT_CLUSTER_CFG_CLONE_LIVEOUT_COMPARE_SUMMARY_RE.search(
                body
            )
        )
        if not summary_match:
            continue
        int_fields = (
            "compare_count",
            "expected_liveout_value_count",
            "unsupported_compare_count",
        )
        summaries.append(
            {
                "status": summary_match.group("status"),
                **{field: int(summary_match.group(field)) for field in int_fields},
                "next_action": summary_match.group("next_action"),
                "authority": summary_match.group("authority"),
            }
        )
    if not summaries:
        return None
    return max(
        summaries,
        key=lambda summary: (
            summary["compare_count"],
            -summary["unsupported_compare_count"],
        ),
    )


