def _parse_repaired_select_only_compact_cluster_cfg_clone_liveout_slot_map(
    ir_text: str,
) -> dict[str, Any] | None:
    named = re.search(
        r"!vlgpu\.eval_hot_path_repaired_select_only_compact_cluster_cfg_clone_liveout_slot_map\s*=\s*!\{(?P<body>[^}]*)\}",
        ir_text,
    )
    if not named:
        return None

    slot_node_ids = [
        match.group("node_id")
        for match in LLVM_METADATA_NODE_ID_RE.finditer(named.group("body"))
    ]
    if not slot_node_ids:
        return None

    node_bodies = {
        match.group("node_id"): match.group("body")
        for match in LLVM_METADATA_NODE_DEF_RE.finditer(ir_text)
    }
    entries: list[dict[str, Any]] = []
    authorities: set[str] = set()
    for node_id in slot_node_ids:
        body = node_bodies.get(node_id)
        if not body:
            continue
        entry_match = (
            LLVM_REPAIRED_SELECT_ONLY_COMPACT_CLUSTER_CFG_CLONE_LIVEOUT_SLOT_MAP_ENTRY_RE.search(
                body
            )
        )
        if not entry_match:
            continue
        authority = entry_match.group("authority")
        authorities.add(authority)
        entries.append(
            {
                "slot": int(entry_match.group("slot")),
                "value_name": entry_match.group("value_name"),
                "block_name": entry_match.group("block_name"),
                "producer_opcode": entry_match.group("producer_opcode"),
                "type_kind": entry_match.group("type_kind"),
                "type_bit_width": int(entry_match.group("type_bit_width")),
                "phi_incoming_count": int(entry_match.group("phi_incoming_count")),
                "phi_internal_incoming_count": int(
                    entry_match.group("phi_internal_incoming_count")
                ),
                "phi_external_incoming_count": int(
                    entry_match.group("phi_external_incoming_count")
                ),
                "phi_distinct_incoming_value_count": int(
                    entry_match.group("phi_distinct_incoming_value_count")
                ),
                "entry_id": int(entry_match.group("entry_id")),
                "component_root_block_name": entry_match.group(
                    "component_root_block_name"
                ),
                "component_root_block_count": int(
                    entry_match.group("component_root_block_count")
                ),
                "expected_store_count": int(entry_match.group("expected_store_count")),
                "expected_capture_block_name": entry_match.group(
                    "expected_capture_block_name"
                ),
                "authority": authority,
            }
        )
    if not entries:
        return None
    entries.sort(key=lambda entry: entry["slot"])
    slots = [entry["slot"] for entry in entries]
    return {
        "status": "prototype_repaired_select_only_compact_cluster_cfg_clone_liveout_slot_map_present",
        "slot_count": len(entries),
        "min_slot": min(slots),
        "max_slot": max(slots),
        "missing_slots": [
            slot for slot in range(max(slots) + 1) if slot not in set(slots)
        ],
        "entries": entries,
        "authority": (
            next(iter(authorities)) if len(authorities) == 1 else "mixed_authority"
        ),
        "next_action": "join_runtime_mismatch_slots_with_original_liveout_slot_map",
    }


