def _parse_repaired_select_only_predicate_context_global_abi_concrete_slots(
    ir_text: str,
) -> dict[str, Any]:
    global_names: list[str] = []
    load_names: list[str] = []
    missing_global_names: list[str] = []
    missing_load_names: list[str] = []
    missing_load_metadata_names: list[str] = []
    for global_name, load_name in EVAL_PREDICATE_CONTEXT_GLOBAL_ABI_SLOTS:
        global_pattern = rf"@{re.escape(global_name)}\s*=\s*internal global"
        if re.search(global_pattern, ir_text):
            global_names.append(global_name)
        else:
            missing_global_names.append(global_name)

        load_pattern = (
            rf"%{re.escape(load_name)}\s*=\s*load volatile [^,\n]+,\s*"
            rf"ptr @{re.escape(global_name)}[^\n]*"
        )
        load_match = re.search(load_pattern, ir_text)
        if load_match:
            load_names.append(load_name)
            if (
                "!vlgpu.eval_hot_path_repaired_select_only_predicate_context_global_abi"
                not in load_match.group(0)
            ):
                missing_load_metadata_names.append(load_name)
        else:
            missing_load_names.append(load_name)
            missing_load_metadata_names.append(load_name)

    return {
        "expected_global_slot_count": len(EVAL_PREDICATE_CONTEXT_GLOBAL_ABI_SLOTS),
        "global_slot_count": len(global_names),
        "global_slot_names": global_names,
        "missing_global_slot_names": missing_global_names,
        "context_load_count": len(load_names),
        "context_load_names": load_names,
        "missing_context_load_names": missing_load_names,
        "context_load_metadata_count": (
            len(load_names) - len([name for name in missing_load_metadata_names if name in load_names])
        ),
        "missing_context_load_metadata_names": missing_load_metadata_names,
        "concrete_abi_available": (
            not missing_global_names
            and not missing_load_names
            and not missing_load_metadata_names
        ),
    }


def _partition_local_guard_refactor_plan(
    reject_reasons: dict[str, Any],
    refactor_shapes: list[dict[str, Any]] | None = None,
    select_only_outline_summary: dict[str, int] | None = None,
    select_only_repair_summary: dict[str, int] | None = None,
    post_select_only_repair_skip_summary: dict[str, int] | None = None,
) -> dict[str, Any]:
    reason_to_refactor = {
        "successor_phi_depends_on_continuation_edge": {
            "refactor": "outline_partition_region_before_phi_join_or_split_successor_phi_edges",
            "why": "continuation edge feeds successor PHIs, so a branch-around guard would change incoming values unless the region is outlined or PHIs are repaired",
        },
        "terminator_not_unconditional_branch": {
            "refactor": "outline_multi_successor_partition_region_or_normalize_continuation_terminator",
            "why": "continuation has multi-successor control flow, so simple branch-around skip cannot preserve local control semantics",
        },
        "continuation_has_side_effect_or_memory_access": {
            "refactor": "outline_effectful_partition_region_with_explicit_state_contract",
            "why": "continuation reads or writes state, so skip authority must be scoped to an outlined region with explicit inputs and outputs",
        },
        "continuation_value_used_outside_block": {
            "refactor": "outline_partition_region_and_return_live_out_values",
            "why": "continuation values escape the block, so guard insertion needs explicit live-out plumbing",
        },
        "continuation_predecessor_count_not_one": {
            "refactor": "split_to_single_entry_partition_region_before_guarding",
            "why": "continuation has multiple predecessors, so a partition-local guard needs a single-entry region",
        },
    }
    normalized_reasons = {
        reason: int(count)
        for reason, count in reject_reasons.items()
        if isinstance(reason, str) and isinstance(count, int) and count > 0
    }
    ranked_reasons = [
        {"reason": reason, "count": count}
        for reason, count in sorted(
            normalized_reasons.items(), key=lambda item: (-item[1], item[0])
        )
    ]
    required_refactors = []
    for item in ranked_reasons:
        mapping = reason_to_refactor.get(item["reason"])
        if not mapping:
            required_refactors.append(
                {
                    "reason": item["reason"],
                    "count": item["count"],
                    "refactor": "inspect_unclassified_partition_reject_reason",
                    "why": "reject reason is not mapped to a partition-local transformation yet",
                }
            )
            continue
        required_refactors.append({"reason": item["reason"], "count": item["count"], **mapping})
    return {
        "status": (
            "partition_local_refactor_plan_available"
            if required_refactors
            else "partition_local_refactor_plan_waiting_for_reject_reasons"
        ),
        "dominant_reject_reason": ranked_reasons[0]["reason"] if ranked_reasons else None,
        "recommended_first_refactor": (
            required_refactors[0]["refactor"] if required_refactors else None
        ),
        "required_refactors": required_refactors,
        "refactor_shapes": refactor_shapes or [],
        "select_only_phi_edge_outline_summary": select_only_outline_summary,
        "select_only_phi_edge_repair_summary": select_only_repair_summary,
        "post_select_only_phi_edge_repair_skip_summary": post_select_only_repair_skip_summary,
    }


def _sanitize_output(text: str, cwd: Path) -> str:
    text = text.replace(cwd.resolve().as_posix(), ".")
    return LOCAL_ABSOLUTE_PATH_RE.sub("<local-absolute-path>", text)


def _existing(paths: tuple[str, ...], repo_dir: Path) -> list[str]:
    return [path for path in paths if (repo_dir / path).exists()]


def find_absolute_upstream_refs(repo_dir: Path) -> list[dict[str, Any]]:
    refs: list[dict[str, Any]] = []
    for path in sorted(repo_dir.rglob("*")):
        if not path.is_file() or path.suffix not in {".v", ".vh"}:
            continue
        try:
            lines = path.read_text(encoding="utf-8").splitlines()
        except UnicodeDecodeError:
            continue
        for lineno, line in enumerate(lines, start=1):
            if ABSOLUTE_UPSTREAM_PREFIX in line:
                refs.append(
                    {
                        "path": path.relative_to(repo_dir).as_posix(),
                        "line": lineno,
                        "kind": "absolute_upstream_path",
                    }
                )
    return refs


def _is_relative_to(path: Path, parent: Path) -> bool:
    try:
        path.resolve().relative_to(parent.resolve())
        return True
    except ValueError:
        return False


def _require_artifact_work_dir(work_dir: Path, cwd: Path) -> None:
    if work_dir.is_absolute():
        raise ValueError("local eval work dir must be relative")
    if not _is_relative_to(cwd / work_dir, cwd / "artifacts"):
        raise ValueError("local eval work dir must be under artifacts/")


def _normalize_upstream_paths(repo_dir: Path) -> int:
    changed = 0
    for path in sorted(repo_dir.rglob("*")):
        if not path.is_file() or path.suffix not in {".v", ".vh"}:
            continue
        text = path.read_text(encoding="utf-8")
        updated = text.replace(ABSOLUTE_UPSTREAM_PREFIX, "")
        if updated != text:
            path.write_text(updated, encoding="utf-8")
            changed += 1
    return changed


def _count_hex_lines(path: Path) -> int:
    return len([line for line in path.read_text(encoding="utf-8").splitlines() if line.strip()])


def _normalize_tb_exp_depth(repo_dir: Path) -> dict[str, Any] | None:
    tb_exp = repo_dir / "sim" / "tb_exp.v"
    z_hex = repo_dir / "generated" / "test_exp_z.hex"
    e_hex = repo_dir / "generated" / "test_exp_e.hex"
    if not tb_exp.exists() or not z_hex.exists() or not e_hex.exists():
        return None
    expected_depth = max(_count_hex_lines(z_hex), _count_hex_lines(e_hex))
    text = tb_exp.read_text(encoding="utf-8")
    match = LOCALPARAM_M_RE.search(text)
    if match:
        old_value = int(match.group(1))
        if old_value == expected_depth:
            return {
                "path": "sim/tb_exp.v",
                "status": "already_matched",
                "depth": expected_depth,
            }
        updated = text[: match.start(1)] + str(expected_depth) + text[match.end(1) :]
        tb_exp.write_text(updated, encoding="utf-8")
        return {
            "path": "sim/tb_exp.v",
            "status": "patched_eval_copy_only",
            "from": old_value,
            "to": expected_depth,
            "reason": "generated/test_exp_*.hex line count exceeds upstream localparam",
        }
    return {"path": "sim/tb_exp.v", "status": "missing_localparam_m"}


def prepare_local_eval_checkout(repo_dir: Path, work_dir: Path, *, cwd: Path) -> dict[str, Any]:
    _require_artifact_work_dir(work_dir, cwd)
    eval_repo_dir = cwd / work_dir / "gateGPT"
    if eval_repo_dir.exists():
        shutil.rmtree(eval_repo_dir)
    eval_repo_dir.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(repo_dir, eval_repo_dir, symlinks=True)
    normalized_file_count = _normalize_upstream_paths(eval_repo_dir)
    exp_depth_fix = _normalize_tb_exp_depth(eval_repo_dir)
    return {
        "eval_repo_dir": _repo_relative(eval_repo_dir, cwd),
        "normalized_absolute_upstream_path_file_count": normalized_file_count,
        "tb_exp_depth_normalization": exp_depth_fix,
    }


def _expand_testbench_files(repo_dir: Path, patterns: tuple[str, ...]) -> list[str]:
    files: list[str] = []
    for pattern in patterns:
        if "*" in pattern:
            files.extend(path.relative_to(repo_dir).as_posix() for path in sorted(repo_dir.glob(pattern)))
        else:
            files.append(pattern)
    return files


def full_testbench_command(testbench: str, files: list[str]) -> list[str]:
    return [
        "verilator",
        *FULL_VERILATOR_FLAGS,
        "--top-module",
        testbench,
        "-I.",
        "-Icore",
        "--Mdir",
        f"obj_{testbench}",
        *files,
    ]


def run_full_testbench(repo_dir: Path, testbench: str, patterns: tuple[str, ...]) -> dict[str, Any]:
    files = _expand_testbench_files(repo_dir, patterns)
    command = full_testbench_command(testbench, files)
    if not shutil.which("verilator"):
        return {
            "testbench": testbench,
            "status": "skipped",
            "reason": "verilator_not_found",
            "build_command": command,
        }
    shutil.rmtree(repo_dir / f"obj_{testbench}", ignore_errors=True)
    build = subprocess.run(
        command,
        cwd=repo_dir,
        text=True,
        capture_output=True,
        check=False,
    )
    run_command = [f"./obj_{testbench}/V{testbench}"]
    if build.returncode != 0:
        return {
            "testbench": testbench,
            "status": "build_failed",
            "build_returncode": build.returncode,
            "build_command": command,
            "build_stdout": _sanitize_output(build.stdout, repo_dir),
            "build_stderr": _sanitize_output(build.stderr, repo_dir),
            "run_command": run_command,
        }
    run = subprocess.run(
        run_command,
        cwd=repo_dir,
        text=True,
        capture_output=True,
        check=False,
    )
    return {
        "testbench": testbench,
        "status": "passed" if run.returncode == 0 else "run_failed",
        "build_returncode": build.returncode,
        "run_returncode": run.returncode,
        "build_command": command,
        "run_command": run_command,
        "build_stdout": _sanitize_output(build.stdout, repo_dir),
        "build_stderr": _sanitize_output(build.stderr, repo_dir),
        "run_stdout": _sanitize_output(run.stdout, repo_dir),
        "run_stderr": _sanitize_output(run.stderr, repo_dir),
    }


def run_full_testbenches(repo_dir: Path) -> list[dict[str, Any]]:
    return [run_full_testbench(repo_dir, testbench, patterns) for testbench, patterns in FULL_TESTBENCHES]


def _readmem_refs_for_testbench(repo_dir: Path, testbench: str) -> list[dict[str, Any]]:
    refs: list[dict[str, Any]] = []
    patterns_by_testbench = {name: patterns for name, patterns in FULL_TESTBENCHES}
    patterns = patterns_by_testbench.get(testbench, (f"sim/{testbench}.v",))
    for rel_path in _expand_testbench_files(repo_dir, patterns):
        source = repo_dir / rel_path
        if not source.exists():
            continue
        for lineno, line in enumerate(source.read_text(encoding="utf-8", errors="ignore").splitlines(), start=1):
            for match in READMEM_RE.finditer(line):
                refs.append(
                    {
                        "source": _repo_relative(source, repo_dir),
                        "line": lineno,
                        "kind": match.group("kind"),
                        "path": match.group("path"),
                    }
                )
    return refs


def _parse_cpu_stdout_contract(run: dict[str, Any]) -> dict[str, Any]:
    stdout = run.get("run_stdout", "")
    lines = [line for line in stdout.splitlines() if line.strip()]
    pass_lines: list[dict[str, Any]] = []
    finish_lines: list[dict[str, Any]] = []
    structured_output_lines: list[str] = []
    for line in lines:
        pass_match = PASS_LINE_RE.match(line)
        if pass_match:
            pass_lines.append(
                {
                    "line": line,
                    "label": pass_match.group("label"),
                    "detail": pass_match.group("detail") or "",
                }
            )
            continue
        finish_match = FINISH_LINE_RE.match(line)
        if finish_match:
            finish_lines.append(
                {
                    "line": line,
                    "source": finish_match.group("source"),
                    "source_line": int(finish_match.group("line")),
                }
            )
            continue
        if not line.startswith("- Verilator:") and not line.startswith("- S i m u l a t i o n"):
            structured_output_lines.append(line)
    return {
        "testbench": run.get("testbench"),
        "run_status": run.get("status"),
        "pass_observable": pass_lines[0] if pass_lines else None,
        "pass_observable_count": len(pass_lines),
        "finish_observable": finish_lines[0] if finish_lines else None,
        "finish_observable_count": len(finish_lines),
        "structured_output_lines": structured_output_lines,
        "stdout_authority_available": bool(pass_lines and finish_lines),
    }


def build_gate_gpt_cpu_output_manifest(eval_repo_dir: Path, testbench_runs: list[dict[str, Any]]) -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    for run in testbench_runs:
        testbench = str(run.get("testbench", ""))
        entry = _parse_cpu_stdout_contract(run)
        readmem_refs = _readmem_refs_for_testbench(eval_repo_dir, testbench) if testbench else []
        entry["readmem_refs"] = readmem_refs
        entry["init_state_contract_required"] = bool(readmem_refs)
        entry["gpu_observable_export_status"] = "not_exported"
        entries.append(entry)

    passed_entries = [entry for entry in entries if entry.get("stdout_authority_available")]
    readmem_required = [entry["testbench"] for entry in entries if entry.get("init_state_contract_required")]
    return {
        "status": "available" if entries and len(passed_entries) == len(entries) else "incomplete",
        "scope": "cpu_verilator_stdout_finish_authority_manifest_for_general_gateGPT_followup",
        "testbench_count": len(entries),
        "stdout_authority_count": len(passed_entries),
        "readmem_init_state_contract_required_testbenches": readmem_required,
        "gpu_stdout_finish_export_claimed": False,
        "gpu_output_manifest_claimed": False,
        "next_contract": "map_cpu_output_manifest_to_gpu_device_observables_or_bench_specific_output_manifest",
        "entries": entries,
    }


def build_gate_gpt_gpu_output_mapping_plan(cpu_output_manifest: dict[str, Any]) -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    for entry in cpu_output_manifest.get("entries", []):
        if not isinstance(entry, dict):
            continue
        testbench = str(entry.get("testbench", ""))
        pass_observable = entry.get("pass_observable") if isinstance(entry.get("pass_observable"), dict) else None
        finish_observable = entry.get("finish_observable") if isinstance(entry.get("finish_observable"), dict) else None
        structured_output_lines = entry.get("structured_output_lines", [])
        readmem_refs = entry.get("readmem_refs", [])
        blockers = [
            "stdout_pass_fail_not_exported_from_gpu",
            "finish_not_exported_from_gpu",
        ]
        status = "blocked_missing_gpu_output_manifest"
        strategy = "bench_specific_gpu_output_manifest_required"
        mapped_gpu_observables: list[str] = []
        if readmem_refs:
            blockers.append("readmem_init_state_contract_required")
        if structured_output_lines:
            blockers.append("structured_stdout_requires_device_observable_schema")
        if testbench == SEMANTIC_CANDIDATE_TESTBENCH:
            status = "covered_by_selected_tb_mathops_policy_without_stdout_finish_export"
            strategy = "selected_manifest_consuming_dut_output_compare"
            mapped_gpu_observables = [
                "tb_mathops__DOT__errors",
                "tb_mathops__DOT__d_quo",
                "tb_mathops__DOT__s_root",
            ]
            blockers = [
                "stdout_pass_fail_not_exported_from_gpu",
                "finish_not_exported_from_gpu",
            ]
        entries.append(
            {
                "testbench": testbench,
                "status": status,
                "strategy": strategy,
                "cpu_pass_label": pass_observable.get("label") if pass_observable else None,
                "cpu_finish_source": finish_observable.get("source") if finish_observable else None,
                "cpu_finish_source_line": finish_observable.get("source_line") if finish_observable else None,
                "structured_output_line_count": len(structured_output_lines)
                if isinstance(structured_output_lines, list)
                else 0,
                "readmem_ref_count": len(readmem_refs) if isinstance(readmem_refs, list) else 0,
                "mapped_gpu_observables": mapped_gpu_observables,
                "gpu_stdout_finish_export_claimed": False,
                "gpu_output_manifest_claimed": False,
                "blockers": blockers,
            }
        )

    covered = [entry for entry in entries if str(entry.get("status", "")).startswith("covered_by_")]
    blocked = [entry for entry in entries if str(entry.get("status", "")).startswith("blocked_")]
    return {
        "status": "partial_tb_mathops_only" if covered and blocked else "blocked_no_gpu_output_mapping",
        "scope": "mapping_plan_from_cpu_stdout_finish_authority_to_gpu_observables",
        "covered_testbenches": [entry["testbench"] for entry in covered],
        "blocked_testbenches": [entry["testbench"] for entry in blocked],
        "gpu_stdout_finish_export_claimed": False,
        "gpu_output_manifest_claimed": False,
        "next_contract": "define_bench_specific_gpu_output_manifest_and_init_state_contracts",
        "entries": entries,
    }


def _mark_mapping_plan_covered(
    mapping_plan: dict[str, Any],
    *,
    testbench: str,
    status: str,
    strategy: str,
    mapped_gpu_observables: list[str],
) -> None:
    for entry in mapping_plan.get("entries", []):
        if entry.get("testbench") != testbench:
            continue
        entry["status"] = status
        entry["strategy"] = strategy
        entry["mapped_gpu_observables"] = mapped_gpu_observables
        entry["gpu_output_manifest_claimed"] = True
        entry["gpu_stdout_finish_export_claimed"] = False
        entry["blockers"] = [
            blocker
            for blocker in entry.get("blockers", [])
            if blocker
            not in {
                "readmem_init_state_contract_required",
                "structured_stdout_requires_device_observable_schema",
            }
        ]
        break
    covered = [
        entry
        for entry in mapping_plan.get("entries", [])
        if str(entry.get("status", "")).startswith("covered_by_")
    ]
    blocked = [
        entry
        for entry in mapping_plan.get("entries", [])
        if str(entry.get("status", "")).startswith("blocked_")
    ]
    mapping_plan["covered_testbenches"] = [entry["testbench"] for entry in covered]
    mapping_plan["blocked_testbenches"] = [entry["testbench"] for entry in blocked]
    if covered and blocked:
        joined = "_".join(mapping_plan["covered_testbenches"])
        mapping_plan["status"] = f"partial_{joined}_only"
    elif covered:
        mapping_plan["status"] = "covered_by_bench_specific_gpu_output_manifests_without_stdout_finish_export"
    else:
        mapping_plan["status"] = "blocked_no_gpu_output_mapping"


def _apply_gpu_smoke_results_to_local_mapping_plan(manifest: dict[str, Any]) -> None:
    local_eval = manifest.get("local_normalized_testcase_execution")
    gpu_smoke = manifest.get("gateGPT_gpu_smoke")
    if not isinstance(local_eval, dict) or not isinstance(gpu_smoke, dict):
        return
    mapping_plan = local_eval.get("gpu_output_mapping_plan")
    analysis = gpu_smoke.get("analysis")
    if not isinstance(mapping_plan, dict) or not isinstance(analysis, dict):
        return
    tb_exp_compare = analysis.get("tb_exp_vector_sequence_compare", {})
    if isinstance(tb_exp_compare, dict) and tb_exp_compare.get("status") == "passed":
        _mark_mapping_plan_covered(
            mapping_plan,
            testbench="tb_exp",
            status="covered_by_tb_exp_vector_sequence_compare_without_stdout_finish_export",
            strategy="bench_specific_gpu_vector_sequence_compare",
            mapped_gpu_observables=[
                "tb_exp__DOT__u_exp__DOT__pos_r",
                "tb_exp__DOT__u_exp__DOT__big_r",
                "tb_exp__DOT__u_exp__DOT__interp",
            ],
        )
    tb_norm_compare = analysis.get("tb_norm_vmem_sequence_compare", {})
    if isinstance(tb_norm_compare, dict) and tb_norm_compare.get("status") == "passed":
        _mark_mapping_plan_covered(
            mapping_plan,
            testbench="tb_norm",
            status="covered_by_tb_norm_vmem_sequence_compare_without_stdout_finish_export",
            strategy="bench_specific_gpu_vmem_output_sequence_compare",
            mapped_gpu_observables=["tb_norm__DOT__u_vmem__DOT__mem[64..87]"],
        )
    tb_matvec_compare = analysis.get("tb_matvec_vmem_sequence_compare", {})
    if isinstance(tb_matvec_compare, dict) and tb_matvec_compare.get("status") == "passed":
        _mark_mapping_plan_covered(
            mapping_plan,
            testbench="tb_matvec",
            status="covered_by_tb_matvec_vmem_sequence_compare_without_stdout_finish_export",
            strategy="bench_specific_gpu_vmem_output_sequence_compare",
            mapped_gpu_observables=["tb_matvec__DOT__u_vmem__DOT__mem[64..87]"],
        )
    tb_attn_compare = analysis.get("tb_attn_vmem_sequence_compare", {})
    if isinstance(tb_attn_compare, dict) and tb_attn_compare.get("status") == "passed":
        _mark_mapping_plan_covered(
            mapping_plan,
            testbench="tb_attn",
            status="covered_by_tb_attn_vmem_sequence_compare_without_stdout_finish_export",
            strategy="bench_specific_gpu_vmem_output_sequence_compare",
            mapped_gpu_observables=["tb_attn__DOT__u_vmem__DOT__mem[864..887]"],
        )
    tb_core_compare = analysis.get("tb_core_structured_sequence_compare", {})
    if isinstance(tb_core_compare, dict) and tb_core_compare.get("status") == "passed":
        _mark_mapping_plan_covered(
            mapping_plan,
            testbench="tb_core",
            status="covered_by_tb_core_structured_sequence_compare_without_stdout_finish_export",
            strategy="bench_specific_gpu_structured_sequence_compare",
            mapped_gpu_observables=[
                "tb_core__DOT__next_token",
                "tb_core__DOT__rng_out",
                "tb_core__DOT__cyc",
                "tb_core__DOT__reported",
                "tb_core__DOT__tot_cyc",
                "tb_core__DOT__tot_tok",
            ],
        )


def _hex_values(path: Path, *, bits: int) -> list[int]:
    if not path.exists():
        return []
    mask = (1 << bits) - 1
    sign_bit = 1 << (bits - 1)
    values: list[int] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        token = line.strip()
        if not token:
            continue
        raw = int(token, 16) & mask
        values.append(raw - (1 << bits) if raw & sign_bit else raw)
    return values


def _field_manifest_from_targets(
    obj_dir: Path,
    targets: tuple[dict[str, str], ...],
    *,
    cwd: Path,
) -> dict[str, Any]:
    if not obj_dir.exists():
        return {
            "status": "missing_obj_dir",
            "obj_dir": _repo_relative(obj_dir, cwd),
            "fields": [],
            "missing_fields": [target["name"] for target in targets],
        }
    try:
        layout = probe_root_layout(obj_dir)
    except (OSError, subprocess.CalledProcessError, ValueError) as exc:
        return {
            "status": "probe_failed",
            "obj_dir": _repo_relative(obj_dir, cwd),
            "error": _sanitize_output(str(exc), cwd),
            "fields": [],
            "missing_fields": [target["name"] for target in targets],
        }
    layout_by_name = {str(entry["name"]): entry for entry in layout}
    fields: list[dict[str, Any]] = []
    missing_fields: list[str] = []
    for target in targets:
        name = target["name"]
        entry = layout_by_name.get(name)
        if entry is None:
            missing_fields.append(name)
            continue
        fields.append(
            {
                "name": name,
                "offset": int(entry["offset"]),
                "size": int(entry["size"]),
                "decl_type": entry.get("decl_type", ""),
                "role": target["role"],
                "use": target["use"],
            }
        )
    return {
        "status": "available" if not missing_fields else "incomplete",
        "obj_dir": _repo_relative(obj_dir, cwd),
        "field_count": len(fields),
        "fields": fields,
        "missing_fields": missing_fields,
    }


def tb_exp_init_output_manifest(eval_repo_dir: Path, *, cwd: Path) -> dict[str, Any]:
    obj_dir = eval_repo_dir / "obj_tb_exp"
    z_hex = eval_repo_dir / "generated" / "test_exp_z.hex"
    e_hex = eval_repo_dir / "generated" / "test_exp_e.hex"
    z_values = _hex_values(z_hex, bits=16)
    e_values = _hex_values(e_hex, bits=16)
    pair_count = min(len(z_values), len(e_values))
    field_manifest = _field_manifest_from_targets(obj_dir, TB_EXP_FIELD_OFFSET_TARGETS, cwd=cwd)
    readmem_contract_status = (
        "available"
        if pair_count > 0
        and len(z_values) == len(e_values)
        and field_manifest.get("status") == "available"
        else "incomplete"
    )
    return {
        "status": "available" if readmem_contract_status == "available" else "incomplete",
        "testbench": "tb_exp",
        "scope": "bench_specific_init_state_and_output_manifest_definition",
        "readmem_init_state_contract_status": readmem_contract_status,
        "readmem_sources": [
            {
                "path": _repo_relative(z_hex, cwd),
                "target_field": "tb_exp__DOT__zs",
                "element_bits": 16,
                "element_count": len(z_values),
            },
            {
                "path": _repo_relative(e_hex, cwd),
                "target_field": "tb_exp__DOT__es",
                "element_bits": 16,
                "element_count": len(e_values),
            },
        ],
        "case_count": pair_count,
        "sample_cases": [
            {"index": index, "z": z_values[index], "expected_e": e_values[index]}
            for index in range(min(pair_count, 5))
        ],
        "field_offset_manifest": field_manifest,
        "output_manifest": {
            "status": "defined_cpu_reference_only",
            "pass_condition": "all compared exp_unit outputs match generated/test_exp_e.hex for every generated/test_exp_z.hex input",
            "cpu_pass_line": "EXP PASS: all 103 cases match",
            "gpu_observable_strategy": "drive tb_exp__DOT__zin from z values and compare reconstructed exp_unit output against e values",
            "gpu_output_manifest_claimed": False,
            "gpu_stdout_finish_export_claimed": False,
            "remaining_gap": (
                "The init-state arrays and observe fields are identified, but the GPU run does not yet execute "
                "the full tb_exp vector sequence or export PASS/finish authority."
            ),
        },
        "next_contract": "tb_exp_gpu_vector_sequence_compare_or_stdout_finish_export",
    }


