def _load_json_if_present(path: Path) -> dict[str, Any] | None:
    if not path.exists():
        return None
    return json.loads(path.read_text(encoding="utf-8"))


def _parse_stage_timing_line(stdout: str) -> tuple[dict[str, float], list[dict[str, Any]]]:
    timings: dict[str, float] = {}
    sequence: list[dict[str, Any]] = []
    for line in stdout.splitlines():
        stripped = line.strip()
        if not stripped.startswith(STAGE_TIMING_LINE_PREFIX):
            continue
        for token in stripped[len(STAGE_TIMING_LINE_PREFIX):].strip().split():
            if "=" not in token:
                continue
            stage, raw_value = token.split("=", 1)
            if not stage:
                continue
            try:
                value = float(raw_value)
            except ValueError:
                continue
            timings[stage] = value
            sequence.append({"stage": stage, "since_previous_ms": value})
    return timings, sequence


def _coerce_runtime_key_value(raw_value: str) -> Any:
    if raw_value == "true":
        return True
    if raw_value == "false":
        return False
    try:
        return int(raw_value)
    except ValueError:
        return raw_value


def _parse_runtime_key_value_body(body: str) -> dict[str, Any]:
    parsed: dict[str, Any] = {}
    for token in body.split():
        if "=" not in token:
            continue
        key, raw_value = token.split("=", 1)
        if not key:
            continue
        parsed[key] = _coerce_runtime_key_value(raw_value)
    return parsed


def _runtime_progress_last_slot(progress: dict[str, Any]) -> int | None:
    slots = progress.get("slots")
    if not isinstance(slots, str):
        return None
    parts = slots.split(",")
    if not parts:
        return None
    try:
        return int(parts[-1])
    except ValueError:
        return None


def _runtime_progress_slot(progress: dict[str, Any], index: int) -> int | None:
    slots = progress.get("slots")
    if not isinstance(slots, str):
        return None
    parts = slots.split(",")
    if index < 0 or index >= len(parts):
        return None
    try:
        return int(parts[index])
    except ValueError:
        return None


def _runtime_progress_marker_record(value: Any) -> int | None:
    if not isinstance(value, int):
        return None
    return value & 0xFFFFFFFF


def _runtime_progress_marker_high_patch_idx(value: Any) -> int | None:
    if not isinstance(value, int):
        return None
    return (value >> 32) & 0xFFFFFFFF


def _adjacent_records_contain_uploaded_offset(
    adjacent_records: Any, offset: int | None, *, excluded_record: int | None
) -> bool:
    if offset is None:
        return False
    for entry in _parse_adjacent_record_entries(adjacent_records):
        record = entry["record"]
        uploaded_offset = entry["uploaded_offset"]
        if record != excluded_record and uploaded_offset == offset:
            return True
    return False


def _adjacent_record_uploaded_offset(
    adjacent_records: Any, target_record: int
) -> int | None:
    for entry in _parse_adjacent_record_entries(adjacent_records):
        if entry["record"] == target_record:
            return entry["uploaded_offset"]
    return None


def _parse_adjacent_record_entries(adjacent_records: Any) -> list[dict[str, Any]]:
    if not isinstance(adjacent_records, str):
        return []
    entries: list[dict[str, Any]] = []
    for raw_record in adjacent_records.split(","):
        parts = raw_record.split(":")
        if len(parts) != 6:
            continue
        try:
            record = int(parts[0])
            host_offset = int(parts[1])
            host_value = int(parts[2])
            uploaded_offset = int(parts[3])
            uploaded_value = int(parts[4])
        except ValueError:
            continue
        entries.append(
            {
                "record": record,
                "host_offset": host_offset,
                "host_value": host_value,
                "uploaded_offset": uploaded_offset,
                "uploaded_value": uploaded_value,
                "read_ok": parts[5] == "true",
            }
        )
    return entries


def _adjacent_record_uploaded_offset_mismatch_records(
    adjacent_records: Any,
) -> list[int]:
    return [
        entry["record"]
        for entry in _parse_adjacent_record_entries(adjacent_records)
        if entry["read_ok"] and entry["uploaded_offset"] != entry["host_offset"]
    ]


def _adjacent_record_uploaded_value_mismatch_records(
    adjacent_records: Any,
) -> list[int]:
    return [
        entry["record"]
        for entry in _parse_adjacent_record_entries(adjacent_records)
        if entry["read_ok"] and entry["uploaded_value"] != entry["host_value"]
    ]


def _parse_runtime_summary(stdout: str) -> dict[str, Any]:
    summary: dict[str, Any] = {}
    stage_timings, stage_sequence = _parse_stage_timing_line(stdout)
    if stage_timings:
        summary["stage_timing_ms"] = stage_timings
        summary["stage_timing_sequence"] = stage_sequence
    gpu_kernel_total = GPU_KERNEL_TOTAL_RE.search(stdout)
    if gpu_kernel_total:
        summary["gpu_kernel_total_ms"] = float(gpu_kernel_total.group("value"))
    gpu_kernel_per_launch = GPU_KERNEL_PER_LAUNCH_RE.search(stdout)
    if gpu_kernel_per_launch:
        summary["gpu_kernel_per_logical_launch_ms"] = float(gpu_kernel_per_launch.group("value"))
    wall_time = WALL_TIME_RE.search(stdout)
    if wall_time:
        summary["wall_time_ms"] = float(wall_time.group("value"))
    state_dump = STATE_DUMP_RE.search(stdout)
    if state_dump:
        summary["state_dump_bytes"] = int(state_dump.group("bytes"))
    if "device 0:" in stdout:
        summary["gpu_device_observed"] = True
    if "gpu_kernel_launches:" in stdout:
        summary["kernel_launch_summary_observed"] = True
    kernel_launches = GPU_KERNEL_LAUNCHES_RE.search(stdout)
    if kernel_launches:
        summary["gpu_kernel_logical_launch_count"] = int(kernel_launches.group("logical"))
        summary["gpu_kernel_actual_launch_count"] = int(kernel_launches.group("actual"))
        summary["gpu_kernel_timing_repeats"] = int(kernel_launches.group("timing_repeats"))
        if kernel_launches.group("ms_per_actual") is not None:
            summary["gpu_kernel_ms_per_actual_launch"] = float(kernel_launches.group("ms_per_actual"))
    feedback_edges = FEEDBACK_EDGES_RE.search(stdout)
    if feedback_edges:
        summary["feedback_edges"] = {
            "requested": feedback_edges.group("requested") == "true",
            "mode": feedback_edges.group("mode"),
            "edge_count": int(feedback_edges.group("edges")),
            "launch_count": int(feedback_edges.group("launched")),
            "kernel": feedback_edges.group("kernel"),
        }
    feedback_increments = FEEDBACK_INCREMENTS_RE.search(stdout)
