def _gpu_ir_definition_status(obj_dir: Path, required_functions: tuple[dict[str, str], ...], *, cwd: Path) -> dict[str, Any]:
    ir_path = obj_dir / "vl_batch_gpu_opt.ll"
    if not ir_path.exists():
        return {
            "status": "missing_ir",
            "ir": _repo_relative(ir_path, cwd),
            "required_functions": required_functions,
        }
    text = ir_path.read_text(encoding="utf-8")
    functions: list[dict[str, Any]] = []
    missing_definitions: list[str] = []
    unused_declarations: list[str] = []
    for required in required_functions:
        symbol = required["symbol"]
        define_present = re.search(rf"(?m)^define\b[^\n@]*@{re.escape(symbol)}\(", text) is not None
        declare_present = re.search(rf"(?m)^declare\b[^\n@]*@{re.escape(symbol)}\(", text) is not None
        call_present = re.search(rf"\bcall\b[^\n@]*@{re.escape(symbol)}\(", text) is not None
        if not define_present and call_present:
            missing_definitions.append(symbol)
        if declare_present and not define_present and not call_present:
            unused_declarations.append(symbol)
        functions.append(
            {
                "symbol": symbol,
                "role": required["role"],
                "define_present": define_present,
                "declare_present": declare_present,
                "call_present": call_present,
            }
        )
    return {
        "status": "complete" if not missing_definitions else "missing_gpu_definitions",
        "ir": _repo_relative(ir_path, cwd),
        "missing_definitions": missing_definitions,
        "unused_declarations": unused_declarations,
        "functions": functions,
    }


def _gpu_kernel_entrypoint_status(obj_dir: Path, kernel_name: str, *, cwd: Path) -> dict[str, Any]:
    ir_path = obj_dir / "vl_batch_gpu_opt.ll"
    if not ir_path.exists():
        return {
            "status": "missing_ir",
            "ir": _repo_relative(ir_path, cwd),
            "kernel": kernel_name,
        }
    text = ir_path.read_text(encoding="utf-8")
    define_present = re.search(rf"(?m)^define\b[^\n@]*@{re.escape(kernel_name)}\(", text) is not None
    annotated = re.search(rf'ptr @{re.escape(kernel_name)}, !"kernel"', text) is not None
    return {
        "status": "available" if define_present and annotated else "missing_kernel_entrypoint",
        "ir": _repo_relative(ir_path, cwd),
        "kernel": kernel_name,
        "define_present": define_present,
        "nvvm_kernel_annotation_present": annotated,
    }


def run_tb_exp_vector_sequence_compare(
    cwd: Path,
    eval_repo_dir: Path,
    init_output_manifest: dict[str, Any],
) -> dict[str, Any]:
    if init_output_manifest.get("status") != "available":
        return {
            "status": "blocked_missing_init_output_manifest",
            "semantic_equivalence_claimed": False,
        }
    obj_dir = eval_repo_dir / "obj_tb_exp"
    offsets = _field_offsets_by_name(init_output_manifest["field_offset_manifest"])
    required = {
        "tb_exp__DOT__clk",
        "tb_exp__DOT__zin",
        "tb_exp__DOT__u_exp__DOT__pos_r",
        "tb_exp__DOT__u_exp__DOT__big_r",
        "tb_exp__DOT__u_exp__DOT__interp",
    }
    missing = sorted(required - set(offsets))
    ir_definition_status = _gpu_ir_definition_status(obj_dir, TB_EXP_GPU_IR_REQUIRED_FUNCTIONS, cwd=cwd)
    if missing:
        return {
            "status": "blocked_incomplete_field_offset_manifest",
            "missing_fields": missing,
            "semantic_equivalence_claimed": False,
            "gpu_ir_definition_status": ir_definition_status,
        }

    z_values = _hex_values(eval_repo_dir / "generated" / "test_exp_z.hex", bits=16)
    expected_values = _hex_values(eval_repo_dir / "generated" / "test_exp_e.hex", bits=16)
    pair_count = min(len(z_values), len(expected_values))
    z_values = z_values[:pair_count]
    expected_values = expected_values[:pair_count]
    patch_script = obj_dir / "tb_exp_vector_sequence_patch.steps"
    trace = obj_dir / "tb_exp_vector_sequence_trace.csv"
    state = obj_dir / "tb_exp_vector_sequence_state.bin"
    lines = _build_tb_exp_vector_sequence_patch_lines(offsets, z_values)
    patch_script.write_text("\n".join(lines) + "\n", encoding="utf-8")
    trace_names = (
        "tb_exp__DOT__clk",
        "tb_exp__DOT__zin",
        "tb_exp__DOT__u_exp__DOT__pos_r",
        "tb_exp__DOT__u_exp__DOT__big_r",
        "tb_exp__DOT__u_exp__DOT__interp",
    )
    command = [
        sys.executable,
        "src/tools/run_vl_hybrid.py",
        "--mdir",
        obj_dir.relative_to(cwd).as_posix(),
        "--nstates",
        "1",
        "--steps",
        str(len(lines)),
        "--patch-script",
        patch_script.relative_to(cwd).as_posix(),
        "--dump-state",
        state.relative_to(cwd).as_posix(),
    ]
    env = {
        "RUN_VL_HYBRID_STEP_TRACE": trace.resolve().as_posix(),
        "RUN_VL_HYBRID_STEP_TRACE_FIELDS": _trace_field_spec(offsets, trace_names),
        "RUN_VL_HYBRID_STEP_TRACE_START": "0",
        "RUN_VL_HYBRID_STEP_TRACE_STRIDE": "1",
        "PYTHONDONTWRITEBYTECODE": "1",
    }
    completed = subprocess.run(command, cwd=cwd, env={**os.environ, **env}, text=True, capture_output=True, check=False)
    rows = _parse_step_trace(trace)
    comparison = _compare_tb_exp_vector_trace(z_values, expected_values, rows)
    passed = (
        completed.returncode == 0
        and comparison["case_count"] == pair_count
        and comparison["mismatch_count"] == 0
        and ir_definition_status["status"] == "complete"
    )
    status = "passed" if passed else "failed_gpu_trace_mismatch_or_incomplete_ir"
    if completed.returncode != 0:
        status = "failed_gpu_run"
    return {
        "status": status,
        "scope": "tb_exp_103_case_gpu_vector_sequence_compare",
        "semantic_equivalence_claimed": bool(passed),
        "stdout_pass_fail_export_claimed": False,
        "finish_export_claimed": False,
        "command": command,
        "patch_script": _repo_relative(patch_script, cwd),
        "trace": _repo_relative(trace, cwd),
        "state_dump": _repo_relative(state, cwd),
        "logical_steps": len(lines),
        "run_returncode": completed.returncode,
        "runtime_summary": _parse_runtime_summary(completed.stdout),
        "comparison": comparison,
        "gpu_ir_definition_status": ir_definition_status,
        "observed_gap": (
            "tb_exp GPU trace does not yet prove exp_unit output equivalence; the current GPU IR keeps "
            "posedge/NBA helper functions as declarations instead of device definitions, so the exp_unit "
            "pipeline state is not a reviewed GPU execution authority."
        )
        if not passed
        else None,
        "output_reconstruction_policy": (
            "eo is reconstructed as pos_r ? 2048 : big_r ? 0 : signed(interp) < 0 ? 0 : signed(interp[15:0])"
        ),
        "stdout_tail": _sanitize_output("\n".join(completed.stdout.splitlines()[-12:]), cwd),
        "stderr_tail": _sanitize_output("\n".join(completed.stderr.splitlines()[-12:]), cwd),
    }


