def run_tb_exp_distinct_state_resident_repeat_median_probe(
    cwd: Path,
    eval_repo_dir: Path,
    init_output_manifest: dict[str, Any],
    *,
    repeat_count: int = 7,
) -> dict[str, Any]:
    runs: list[dict[str, Any]] = []
    for repeat in range(repeat_count):
        result = run_tb_exp_distinct_state_resident_patch_probe(cwd, eval_repo_dir, init_output_manifest)
        summary = result.get("runtime_summary", {})
        comparison = result.get("comparison", {})
        runs.append(
            {
                "repeat": repeat,
                "status": result.get("status"),
                "run_returncode": result.get("run_returncode"),
                "runtime_summary": summary,
                "comparison": comparison,
                "stdout_tail": result.get("stdout_tail", ""),
                "stderr_tail": result.get("stderr_tail", ""),
            }
        )
    passed = [
        run
        for run in runs
        if run["status"] == "passed"
        and isinstance(run.get("runtime_summary"), dict)
        and isinstance(run["runtime_summary"].get("wall_time_ms"), (int, float))
        and isinstance(run["runtime_summary"].get("gpu_kernel_total_ms"), (int, float))
    ]
    wall_values = [run["runtime_summary"]["wall_time_ms"] for run in passed]
    kernel_values = [run["runtime_summary"]["gpu_kernel_total_ms"] for run in passed]
    first_passed = passed[0] if passed else {}
    first_comparison = first_passed.get("comparison", {}) if isinstance(first_passed, dict) else {}
    wall_median = statistics.median(wall_values) if wall_values else None
    kernel_median = statistics.median(kernel_values) if kernel_values else None
    return {
        "status": "passed" if len(passed) == repeat_count else "incomplete",
        "scope": "tb_exp_distinct_z_values_resident_patch_schedule_repeat_median",
        "repeat_count": repeat_count,
        "passed_count": len(passed),
        "semantic_equivalence_claimed": len(passed) == repeat_count,
        "speedup_claimed": False,
        "usefulness_claimed": False,
        "mixed_scenario_claimed": len(passed) == repeat_count,
        "resident_patch_schedule_claimed": len(passed) == repeat_count,
        "runtime_summary": {
            "gpu_kernel_total_ms": kernel_median,
            "wall_time_ms": wall_median,
        },
        "gpu_kernel_total_ms_min": min(kernel_values) if kernel_values else None,
        "gpu_kernel_total_ms_median": kernel_median,
        "gpu_kernel_total_ms_max": max(kernel_values) if kernel_values else None,
        "wall_time_ms_min": min(wall_values) if wall_values else None,
        "wall_time_ms_median": wall_median,
        "wall_time_ms_max": max(wall_values) if wall_values else None,
        "case_count": first_comparison.get("case_count"),
        "passed_case_count": first_comparison.get("passed_count"),
        "mismatch_count": first_comparison.get("mismatch_count"),
        "runs": runs,
        "interpretation": (
            "Repeat-median timing for the resident distinct tb_exp state batch. "
            "This is stronger timing evidence than a single sample, but speedup/usefulness remain unclaimed "
            "until the comparison policy and resident coverage are broadened beyond this narrow two-step bench."
        ),
    }


def run_tb_exp_cpu_baseline_timing(
    cwd: Path,
    eval_repo_dir: Path,
    *,
    repeat_count: int = 7,
) -> dict[str, Any]:
    command = ["./obj_tb_exp/Vtb_exp"]
    executable = eval_repo_dir / "obj_tb_exp" / "Vtb_exp"
    if not executable.exists():
        return {
            "status": "blocked_missing_cpu_verilator_binary",
            "command": command,
            "speedup_claimed": False,
            "usefulness_claimed": False,
        }
    runs: list[dict[str, Any]] = []
    for repeat in range(repeat_count):
        start = time.perf_counter()
        completed = subprocess.run(
            command,
            cwd=eval_repo_dir,
            text=True,
            capture_output=True,
            check=False,
        )
        wall_ms = (time.perf_counter() - start) * 1000.0
        stdout_lines = completed.stdout.splitlines()
        pass_line = next((line for line in stdout_lines if line.startswith("EXP PASS")), None)
        runs.append(
            {
                "repeat": repeat,
                "status": "passed" if completed.returncode == 0 and pass_line else "failed",
                "returncode": completed.returncode,
                "wall_time_ms": wall_ms,
                "pass_line": pass_line,
                "stdout_tail": _sanitize_output("\n".join(stdout_lines[-5:]), cwd),
                "stderr_tail": _sanitize_output("\n".join(completed.stderr.splitlines()[-5:]), cwd),
            }
        )
    passed = [run for run in runs if run["status"] == "passed" and isinstance(run.get("wall_time_ms"), float)]
    wall_values = [run["wall_time_ms"] for run in passed]
    return {
        "status": "passed" if len(passed) == repeat_count else "incomplete",
        "scope": "tb_exp_cpu_verilator_103_case_process_wall_baseline",
        "command": command,
        "repeat_count": repeat_count,
        "passed_count": len(passed),
        "case_count": 103,
        "wall_time_ms_min": min(wall_values) if wall_values else None,
        "wall_time_ms_median": statistics.median(wall_values) if wall_values else None,
        "wall_time_ms_max": max(wall_values) if wall_values else None,
        "runs": runs,
        "speedup_claimed": False,
        "usefulness_claimed": False,
        "interpretation": (
            "CPU process-wall baseline for the same tb_exp 103-case Verilator testbench. "
            "This includes process startup and Verilator harness overhead, so it is a conservative comparison point, not a standalone usefulness claim."
        ),
    }


def compare_tb_exp_distinct_gpu_to_cpu_baseline(
    gpu_probe: dict[str, Any],
    cpu_baseline: dict[str, Any],
) -> dict[str, Any]:
    gpu_wall = gpu_probe.get("runtime_summary", {}).get("wall_time_ms") if isinstance(gpu_probe.get("runtime_summary"), dict) else None
    gpu_kernel = gpu_probe.get("runtime_summary", {}).get("gpu_kernel_total_ms") if isinstance(gpu_probe.get("runtime_summary"), dict) else None
    cpu_median = cpu_baseline.get("wall_time_ms_median")
    wall_speedup = None
    kernel_vs_cpu = None
    if isinstance(gpu_wall, (int, float)) and isinstance(cpu_median, (int, float)) and gpu_wall > 0:
        wall_speedup = cpu_median / gpu_wall
    if isinstance(gpu_kernel, (int, float)) and isinstance(cpu_median, (int, float)) and gpu_kernel > 0:
        kernel_vs_cpu = cpu_median / gpu_kernel
    return {
        "status": "measured" if wall_speedup is not None else "incomplete",
        "scope": "tb_exp_distinct_state_gpu_vs_cpu_process_wall_baseline",
        "gpu_scope": gpu_probe.get("scope"),
        "cpu_scope": cpu_baseline.get("scope"),
        "gpu_wall_time_ms": gpu_wall,
        "gpu_kernel_total_ms": gpu_kernel,
        "cpu_wall_time_ms_median": cpu_median,
        "wall_speedup_observed": wall_speedup,
        "kernel_vs_cpu_wall_ratio_observed": kernel_vs_cpu,
        "speedup_claimed": False,
        "usefulness_claimed": False,
        "claim_blockers": [
            "CPU baseline is process-wall timing for the Verilator binary, not an in-process apples-to-apples kernel baseline",
            "GPU comparison may still include runtime schedule upload, state dump, and launcher overhead",
            "broader resident state-indexed patch scheduling and multi-step or multi-token coverage are still needed before a stable usefulness claim",
        ],
    }


def compare_tb_exp_resident_to_nonresident(
    resident_probe: dict[str, Any],
    nonresident_probe: dict[str, Any],
) -> dict[str, Any]:
    resident_summary = resident_probe.get("runtime_summary", {})
    nonresident_summary = nonresident_probe.get("runtime_summary", {})
    resident_wall = resident_summary.get("wall_time_ms") if isinstance(resident_summary, dict) else None
    nonresident_wall = nonresident_summary.get("wall_time_ms") if isinstance(nonresident_summary, dict) else None
    resident_kernel = resident_summary.get("gpu_kernel_total_ms") if isinstance(resident_summary, dict) else None
    nonresident_kernel = nonresident_summary.get("gpu_kernel_total_ms") if isinstance(nonresident_summary, dict) else None
    wall_speedup = None
    kernel_speedup = None
    if isinstance(resident_wall, (int, float)) and resident_wall > 0 and isinstance(nonresident_wall, (int, float)):
        wall_speedup = nonresident_wall / resident_wall
    if isinstance(resident_kernel, (int, float)) and resident_kernel > 0 and isinstance(nonresident_kernel, (int, float)):
        kernel_speedup = nonresident_kernel / resident_kernel
    return {
        "status": "measured" if wall_speedup is not None or kernel_speedup is not None else "incomplete",
        "scope": "tb_exp_distinct_state_resident_vs_nonresident_patch_schedule",
        "resident_scope": resident_probe.get("scope"),
        "nonresident_scope": nonresident_probe.get("scope"),
        "wall_speedup_observed": wall_speedup,
        "kernel_speedup_observed": kernel_speedup,
        "speedup_claimed": False,
        "usefulness_claimed": False,
        "claim_blockers": [
            "resident/nonresident comparison is a single report sample, not a repeat median",
            "CPU baseline remains process-wall timing, not an in-process apples-to-apples kernel baseline",
            "general gateGPT stdout/finish authority and larger resident workloads remain unproven",
        ],
    }


def _run_vmem_sequence_compare(
    cwd: Path,
    eval_repo_dir: Path,
    init_output_manifest: dict[str, Any],
    *,
    testbench: str,
    input_hex: str | list[str],
    output_hex: str,
    done_field: str,
    output_base: int = 64,
    patch_builder: Callable[[dict[str, dict[str, int]], list[int]], list[str]],
    state_comparer: Callable[[Path, dict[str, dict[str, int]], list[int]], dict[str, Any]],
) -> dict[str, Any]:
    if init_output_manifest.get("status") != "available":
        return {
            "status": "blocked_missing_init_output_manifest",
            "semantic_equivalence_claimed": False,
        }
    obj_dir = eval_repo_dir / f"obj_{testbench}"
    offsets = _field_offsets_by_name(init_output_manifest["field_offset_manifest"])
    required = {
        f"{testbench}__DOT__clk",
        f"{testbench}__DOT__resetn",
        f"{testbench}__DOT__start",
        f"{testbench}__DOT__load",
        f"{testbench}__DOT__tb_we",
        f"{testbench}__DOT__{done_field}",
        f"{testbench}__DOT__u_vmem__DOT__mem",
    }
    missing = sorted(required - set(offsets))
    if missing:
        return {
            "status": "blocked_incomplete_field_offset_manifest",
            "missing_fields": missing,
            "semantic_equivalence_claimed": False,
        }

    input_hex_paths = [input_hex] if isinstance(input_hex, str) else input_hex
    input_values: list[int] = []
    for input_path in input_hex_paths:
        input_values.extend(_hex_values(eval_repo_dir / "generated" / input_path, bits=16))
    expected_values = _hex_values(eval_repo_dir / "generated" / output_hex, bits=16)
    pair_count = len(expected_values)
    expected_values = expected_values[:pair_count]
    patch_script = obj_dir / f"{testbench}_vmem_sequence_patch.steps"
    trace = obj_dir / f"{testbench}_vmem_sequence_trace.csv"
    state = obj_dir / f"{testbench}_vmem_sequence_state.bin"
    lines = patch_builder(offsets, input_values)
    patch_script.write_text("\n".join(lines) + "\n", encoding="utf-8")
    command = [
        sys.executable,
        "src/tools/run_vl_hybrid.py",
        "--mdir",
        obj_dir.relative_to(cwd).as_posix(),
        "--nstates",
        "1",
        "--steps",
        str(len(lines)),
        "--patch-script",
        patch_script.relative_to(cwd).as_posix(),
        "--dump-state",
        state.relative_to(cwd).as_posix(),
    ]
    env = {
        "RUN_VL_HYBRID_STEP_TRACE": trace.resolve().as_posix(),
        "RUN_VL_HYBRID_STEP_TRACE_FIELDS": _trace_field_spec(
            offsets,
            (
                f"{testbench}__DOT__clk",
                f"{testbench}__DOT__resetn",
                f"{testbench}__DOT__start",
                f"{testbench}__DOT__{done_field}",
            ),
        ),
        "RUN_VL_HYBRID_STEP_TRACE_START": "0",
        "RUN_VL_HYBRID_STEP_TRACE_STRIDE": "1",
        "PYTHONDONTWRITEBYTECODE": "1",
    }
    completed = subprocess.run(command, cwd=cwd, env={**os.environ, **env}, text=True, capture_output=True, check=False)
    comparison = state_comparer(state, offsets, expected_values)
    rows = _parse_step_trace(trace)
    done_steps = [row.get("step") for row in rows if row.get(done_field)]
    passed = completed.returncode == 0 and comparison["case_count"] == pair_count and comparison["mismatch_count"] == 0
    status = "passed" if passed else "failed_gpu_state_mismatch"
    if completed.returncode != 0:
        status = "failed_gpu_run"
    return {
        "status": status,
        "scope": f"{testbench}_{pair_count}_output_gpu_vmem_sequence_compare",
        "semantic_equivalence_claimed": bool(passed),
        "stdout_pass_fail_export_claimed": False,
        "finish_export_claimed": False,
        "command": command,
        "patch_script": _repo_relative(patch_script, cwd),
        "trace": _repo_relative(trace, cwd),
        "state_dump": _repo_relative(state, cwd),
        "logical_steps": len(lines),
        "run_returncode": completed.returncode,
        "runtime_summary": _parse_runtime_summary(completed.stdout),
        "comparison": comparison,
        "done_observed": bool(done_steps),
        "first_done_step": done_steps[0] if done_steps else None,
        "output_window": f"{testbench}__DOT__u_vmem__DOT__mem[{output_base}..{output_base + pair_count - 1}]",
        "stdout_tail": _sanitize_output("\n".join(completed.stdout.splitlines()[-12:]), cwd),
        "stderr_tail": _sanitize_output("\n".join(completed.stderr.splitlines()[-12:]), cwd),
    }


