    def _join_runtime_missing_slots(slots: list[int]) -> list[dict[str, Any]]:
        joined = []
        for slot in slots:
            mapped_entry = liveout_slot_entries_by_index.get(slot, {})
            joined.append(
                {
                    "slot": slot,
                    "value_name": mapped_entry.get("value_name"),
                    "block_name": mapped_entry.get("block_name"),
                    "producer_opcode": mapped_entry.get("producer_opcode"),
                    "type_kind": mapped_entry.get("type_kind"),
                    "type_bit_width": mapped_entry.get("type_bit_width"),
                    "phi_incoming_count": mapped_entry.get("phi_incoming_count"),
                    "phi_internal_incoming_count": mapped_entry.get(
                        "phi_internal_incoming_count"
                    ),
                    "phi_external_incoming_count": mapped_entry.get(
                        "phi_external_incoming_count"
                    ),
                    "phi_distinct_incoming_value_count": mapped_entry.get(
                        "phi_distinct_incoming_value_count"
                    ),
                    "entry_id": mapped_entry.get("entry_id"),
                    "component_root_block_name": mapped_entry.get(
                        "component_root_block_name"
                    ),
                    "component_root_block_count": mapped_entry.get(
                        "component_root_block_count"
                    ),
                    "expected_store_count": mapped_entry.get("expected_store_count"),
                    "expected_capture_block_name": mapped_entry.get(
                        "expected_capture_block_name"
                    ),
                }
            )
        return joined

    def _group_runtime_missing_slots(
        joined_slots: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        grouped_slots: dict[str, list[dict[str, Any]]] = {}
        for entry in joined_slots:
            block_name = str(entry.get("block_name") or "<unknown>")
            grouped_slots.setdefault(block_name, []).append(entry)
        groups = []
        for block_name, entries in sorted(grouped_slots.items()):
            phi_incoming_counts = sorted(
                {
                    int(entry["phi_incoming_count"])
                    for entry in entries
                    if isinstance(entry.get("phi_incoming_count"), int)
                }
            )
            phi_external_incoming_counts = sorted(
                {
                    int(entry["phi_external_incoming_count"])
                    for entry in entries
                    if isinstance(entry.get("phi_external_incoming_count"), int)
                }
            )
            entry_ids = sorted(
                {
                    int(entry["entry_id"])
                    for entry in entries
                    if isinstance(entry.get("entry_id"), int)
                }
            )
            component_root_block_names = sorted(
                {
                    str(entry["component_root_block_name"])
                    for entry in entries
                    if entry.get("component_root_block_name") is not None
                }
            )
            expected_store_counts = sorted(
                {
                    int(entry["expected_store_count"])
                    for entry in entries
                    if isinstance(entry.get("expected_store_count"), int)
                }
            )
            expected_capture_block_names = sorted(
                {
                    str(entry["expected_capture_block_name"])
                    for entry in entries
                    if entry.get("expected_capture_block_name") is not None
                }
            )
            groups.append(
                {
                    "block_name": block_name,
                    "slot_count": len(entries),
                    "slots": [entry["slot"] for entry in entries],
                    "producer_opcodes": sorted(
                        {
                            str(entry["producer_opcode"])
                            for entry in entries
                            if entry.get("producer_opcode") is not None
                        }
                    ),
                    "phi_incoming_counts": phi_incoming_counts,
                    "phi_external_incoming_counts": phi_external_incoming_counts,
                    "entry_ids": entry_ids,
                    "component_root_block_names": component_root_block_names,
                    "component_root_block_counts": sorted(
                        {
                            int(entry["component_root_block_count"])
                            for entry in entries
                            if isinstance(
                                entry.get("component_root_block_count"), int
                            )
                        }
                    ),
                    "expected_store_counts": expected_store_counts,
                    "expected_capture_block_names": expected_capture_block_names,
                    "all_phi_incoming_internal": phi_external_incoming_counts
                    in ([], [0]),
                }
            )
        return groups

