def _run_tb_mathops_one_clocked_case(
    cwd: Path,
    obj_dir: Path,
    offsets: dict[str, dict[str, int]],
    *,
    kind: str,
    input_value: int,
    denominator: int | None,
    expected: int,
) -> dict[str, Any]:
    case_name = "div_10962944_by_24" if kind == "divider" else "sqrt_456789"
    patch_script = obj_dir / f"tb_mathops_{case_name}_patch.steps"
    trace = obj_dir / f"tb_mathops_{case_name}_trace.csv"
    state = obj_dir / f"tb_mathops_{case_name}_state.bin"
    lines = _build_tb_mathops_clocked_patch_lines(
        offsets,
        kind=kind,
        input_value=input_value,
        denominator=denominator,
    )
    patch_script.write_text("\n".join(lines) + "\n", encoding="utf-8")
    if kind == "divider":
        trace_names = (
            "tb_mathops__DOT__clk",
            "tb_mathops__DOT__resetn",
            "tb_mathops__DOT__d_start",
            "tb_mathops__DOT__d_done",
            "tb_mathops__DOT__d_quo",
        )
        done_label = "d_done"
        result_label = "d_quo"
    else:
        trace_names = (
            "tb_mathops__DOT__clk",
            "tb_mathops__DOT__resetn",
            "tb_mathops__DOT__s_start",
            "tb_mathops__DOT__s_done",
            "tb_mathops__DOT__s_root",
        )
        done_label = "s_done"
        result_label = "s_root"
    command = [
        sys.executable,
        "src/tools/run_vl_hybrid.py",
        "--mdir",
        obj_dir.relative_to(cwd).as_posix(),
        "--nstates",
        "1",
        "--steps",
        str(len(lines)),
        "--patch-script",
        patch_script.relative_to(cwd).as_posix(),
        "--dump-state",
        state.relative_to(cwd).as_posix(),
    ]
    env = {
        "RUN_VL_HYBRID_STEP_TRACE": trace.resolve().as_posix(),
        "RUN_VL_HYBRID_STEP_TRACE_FIELDS": _trace_field_spec(offsets, trace_names),
        "RUN_VL_HYBRID_STEP_TRACE_START": "0",
        "RUN_VL_HYBRID_STEP_TRACE_STRIDE": "1",
        "PYTHONDONTWRITEBYTECODE": "1",
    }
    run_env = {**os.environ, **env}
    completed = subprocess.run(command, cwd=cwd, env=run_env, text=True, capture_output=True, check=False)
    rows = _parse_step_trace(trace)
    done_rows = [row for row in rows if row.get(done_label)]
    final_field_names = trace_names + ("tb_mathops__DOT__errors",)
    final_fields = _read_state_fields(state, offsets, final_field_names)
    result_value = final_fields.get(result_label)
    if done_rows:
        result_value = done_rows[-1].get(result_label, result_value)
    passed = completed.returncode == 0 and bool(done_rows) and result_value == expected
    return {
        "case": case_name,
        "kind": kind,
        "status": "passed" if passed else "failed",
        "command": command,
        "patch_script": _repo_relative(patch_script, cwd),
        "trace": _repo_relative(trace, cwd),
        "state_dump": _repo_relative(state, cwd),
        "logical_steps": len(lines),
        "run_returncode": completed.returncode,
        "runtime_summary": _parse_runtime_summary(completed.stdout),
        "first_done_step": done_rows[0]["step"] if done_rows else None,
        "expected_result": expected,
        "observed_result": result_value,
        "final_fields": final_fields,
        "stdout_tail": _sanitize_output("\n".join(completed.stdout.splitlines()[-12:]), cwd),
        "stderr_tail": _sanitize_output("\n".join(completed.stderr.splitlines()[-12:]), cwd),
    }


def _done_events(rows: list[dict[str, int]], done_label: str, result_label: str) -> list[dict[str, int]]:
    events: list[dict[str, int]] = []
    previous_done = 0
    for row in rows:
        done = row.get(done_label, 0)
        if done and not previous_done:
            events.append(
                {
                    "step": row.get("step", -1),
                    "observed_result": row.get(result_label),
                }
            )
        previous_done = done
    return events


def _compare_tb_mathops_events(expected_cases: tuple[dict[str, int | str], ...], events: list[dict[str, int]]) -> list[dict[str, Any]]:
    compared: list[dict[str, Any]] = []
    for index, expected_case in enumerate(expected_cases):
        event = events[index] if index < len(events) else None
        observed = event.get("observed_result") if event else None
        expected = int(expected_case["expected"])
        compared.append(
            {
                "case": expected_case["case"],
                "expected_result": expected,
                "observed_result": observed,
                "done_step": event.get("step") if event else None,
                "status": "passed" if observed == expected else "failed",
            }
        )
    if len(events) > len(expected_cases):
        for event in events[len(expected_cases) :]:
            compared.append(
                {
                    "case": "unexpected_extra_done_event",
                    "expected_result": None,
                    "observed_result": event.get("observed_result"),
                    "done_step": event.get("step"),
                    "status": "failed",
                }
            )
    return compared


def _tb_mathops_pass_fail_policy(full_sequence: dict[str, Any]) -> dict[str, Any]:
    divider_cases = full_sequence.get("divider_cases", [])
    sqrt_cases = full_sequence.get("sqrt_cases", [])
    all_cases = [*divider_cases, *sqrt_cases]
    all_cases_passed = bool(all_cases) and all(case.get("status") == "passed" for case in all_cases)
    expected_case_count = len(TB_MATHOPS_DIV_CASES) + len(TB_MATHOPS_SQRT_CASES)
    observed_case_count = len(all_cases)
    final_fields = full_sequence.get("final_fields", {})
    errors_zero = isinstance(final_fields, dict) and final_fields.get("errors") == 0
    passed = (
        full_sequence.get("status") == "passed"
        and observed_case_count == expected_case_count
        and all_cases_passed
        and errors_zero
    )
    return {
        "status": "passed" if passed else "failed",
        "policy": "tb_mathops_manifest_consuming_dut_output_compare",
        "cpu_authority": "tb_mathops initial block prints MATHOPS PASS when errors == 0 after six divider and seven sqrt checks",
        "gpu_authority": (
            "generated clocked patch sequence drives the same six divider and seven sqrt inputs, "
            "then compares d_done/d_quo and s_done/s_root against the CPU reference values"
        ),
        "stdout_pass_fail_export_claimed": False,
        "finish_export_claimed": False,
        "selected_testcase_pass_fail_policy_claimed": bool(passed),
        "expected_case_count": expected_case_count,
        "observed_case_count": observed_case_count,
        "all_cases_passed": all_cases_passed,
        "final_errors_zero": errors_zero,
        "remaining_generalization_gap": (
            "This policy is reviewed only for tb_mathops DUT outputs; other gateGPT benches still need "
            "readmem/init-state contracts and PASS/FAIL or output manifests."
        ),
    }


def _run_tb_mathops_full_sequence_compare(
    cwd: Path,
    obj_dir: Path,
    offsets: dict[str, dict[str, int]],
) -> dict[str, Any]:
    patch_script = obj_dir / "tb_mathops_full_sequence_patch.steps"
    trace = obj_dir / "tb_mathops_full_sequence_trace.csv"
    state = obj_dir / "tb_mathops_full_sequence_state.bin"
    lines = _build_tb_mathops_full_sequence_patch_lines(offsets)
    patch_script.write_text("\n".join(lines) + "\n", encoding="utf-8")
    trace_names = (
        "tb_mathops__DOT__clk",
        "tb_mathops__DOT__resetn",
        "tb_mathops__DOT__d_start",
        "tb_mathops__DOT__d_done",
        "tb_mathops__DOT__d_quo",
        "tb_mathops__DOT__s_start",
        "tb_mathops__DOT__s_done",
        "tb_mathops__DOT__s_root",
    )
    command = [
        sys.executable,
        "src/tools/run_vl_hybrid.py",
        "--mdir",
        obj_dir.relative_to(cwd).as_posix(),
        "--nstates",
        "1",
        "--steps",
        str(len(lines)),
        "--patch-script",
        patch_script.relative_to(cwd).as_posix(),
        "--dump-state",
        state.relative_to(cwd).as_posix(),
    ]
    env = {
        "RUN_VL_HYBRID_STEP_TRACE": trace.resolve().as_posix(),
        "RUN_VL_HYBRID_STEP_TRACE_FIELDS": _trace_field_spec(offsets, trace_names),
        "RUN_VL_HYBRID_STEP_TRACE_START": "0",
        "RUN_VL_HYBRID_STEP_TRACE_STRIDE": "1",
        "PYTHONDONTWRITEBYTECODE": "1",
    }
    completed = subprocess.run(command, cwd=cwd, env={**os.environ, **env}, text=True, capture_output=True, check=False)
    rows = _parse_step_trace(trace)
    divider_events = _done_events(rows, "d_done", "d_quo")
    sqrt_events = _done_events(rows, "s_done", "s_root")
    divider_cases = _compare_tb_mathops_events(TB_MATHOPS_DIV_CASES, divider_events)
    sqrt_cases = _compare_tb_mathops_events(TB_MATHOPS_SQRT_CASES, sqrt_events)
    final_fields = _read_state_fields(
        state,
        offsets,
        (
            "tb_mathops__DOT__clk",
            "tb_mathops__DOT__resetn",
            "tb_mathops__DOT__d_done",
            "tb_mathops__DOT__d_quo",
            "tb_mathops__DOT__s_done",
            "tb_mathops__DOT__s_root",
            "tb_mathops__DOT__errors",
        ),
    )
    all_cases = divider_cases + sqrt_cases
    passed = completed.returncode == 0 and all(case["status"] == "passed" for case in all_cases)
    result = {
        "status": "passed" if passed else "failed",
        "scope": "full_six_divider_plus_seven_sqrt_tb_mathops_sequence",
        "semantic_equivalence_claimed": bool(passed),
        "pass_fail_stdout_export_claimed": False,
        "command": command,
        "patch_script": _repo_relative(patch_script, cwd),
        "trace": _repo_relative(trace, cwd),
        "state_dump": _repo_relative(state, cwd),
        "logical_steps": len(lines),
        "run_returncode": completed.returncode,
        "runtime_summary": _parse_runtime_summary(completed.stdout),
        "divider_done_event_count": len(divider_events),
        "sqrt_done_event_count": len(sqrt_events),
        "divider_cases": divider_cases,
        "sqrt_cases": sqrt_cases,
        "final_fields": final_fields,
        "stdout_tail": _sanitize_output("\n".join(completed.stdout.splitlines()[-12:]), cwd),
        "stderr_tail": _sanitize_output("\n".join(completed.stderr.splitlines()[-12:]), cwd),
        "remaining_work": [
            "export or preserve VL_WRITEF_NX/VL_FINISH_MT PASS/FAIL and finish authority as device-visible observables",
            "batch independent scenarios as states before making speedup or usefulness claims",
        ],
    }
    result["selected_testcase_pass_fail_policy"] = _tb_mathops_pass_fail_policy(result)
    return result


def run_tb_mathops_clocked_patch_semantic_smoke(
    cwd: Path,
    eval_repo_dir: Path,
    field_offset_manifest: dict[str, Any],
) -> dict[str, Any]:
    if field_offset_manifest.get("status") != "available":
        return {
            "status": "blocked_missing_field_offset_manifest",
            "semantic_equivalence_claimed": False,
        }
    obj_dir = eval_repo_dir / f"obj_{SEMANTIC_CANDIDATE_TESTBENCH}"
    offsets = _field_offsets_by_name(field_offset_manifest)
    required = {
        "tb_mathops__DOT__clk",
        "tb_mathops__DOT__resetn",
        "tb_mathops__DOT__d_start",
        "tb_mathops__DOT__d_num",
        "tb_mathops__DOT__d_den",
        "tb_mathops__DOT__d_done",
        "tb_mathops__DOT__d_quo",
        "tb_mathops__DOT__s_start",
        "tb_mathops__DOT__s_rad",
        "tb_mathops__DOT__s_done",
        "tb_mathops__DOT__s_root",
        "tb_mathops__DOT__errors",
    }
    missing = sorted(required - set(offsets))
    if missing:
        return {
            "status": "blocked_incomplete_field_offset_manifest",
            "missing_fields": missing,
            "semantic_equivalence_claimed": False,
        }
    cases = [
        _run_tb_mathops_one_clocked_case(
            cwd,
            obj_dir,
            offsets,
            kind="divider",
            input_value=10962944,
            denominator=24,
            expected=456789,
        ),
        _run_tb_mathops_one_clocked_case(
            cwd,
            obj_dir,
            offsets,
            kind="sqrt",
            input_value=456789,
            denominator=None,
            expected=675,
        ),
    ]
    full_sequence = _run_tb_mathops_full_sequence_compare(cwd, obj_dir, offsets)
    return {
        "status": "passed" if all(case["status"] == "passed" for case in cases) else "failed",
        "scope": "single_divider_case_and_single_sqrt_case_only",
        "semantic_equivalence_claimed": False,
        "full_tb_mathops_pass_fail_equivalence_claimed": False,
        "cases": cases,
        "full_sequence_compare": full_sequence,
        "remaining_work": [
            "export or preserve PASS/FAIL and finish authority instead of relying on host I/O stubs",
            "batch independent scenarios as states before making speedup or usefulness claims",
        ],
    }


def run_gpu_smoke_for_testbench(cwd: Path, eval_repo_dir: Path, testbench: str, *, jobs: int) -> dict[str, Any]:
    obj_dir = eval_repo_dir / f"obj_{testbench}"
    build_command = gpu_build_command(obj_dir.relative_to(cwd), jobs=jobs)
    if not obj_dir.exists():
        return {
            "testbench": testbench,
            "status": "missing_obj_dir",
            "build_command": build_command,
        }
    build = subprocess.run(build_command, cwd=cwd, text=True, capture_output=True, check=False)
    result: dict[str, Any] = {
        "testbench": testbench,
        "build_command": build_command,
        "build_returncode": build.returncode,
        "build_status": "passed" if build.returncode == 0 else "failed",
    }
    result.update(_metadata_summary(obj_dir, cwd))
    if build.returncode != 0:
        result["status"] = "gpu_ptx_build_failed"
        result["build_tail"] = _sanitize_output("\n".join(build.stderr.splitlines()[-20:]), cwd)
        return result

    dump_state = obj_dir / "gpu_smoke_state.bin"
    launch_command = gpu_launch_command(obj_dir.relative_to(cwd), dump_state.relative_to(cwd))
    if "--trace-stages" not in launch_command:
        launch_command.append("--trace-stages")
    launch_timeout_seconds = int(os.environ.get("GATEGPT_GPU_SMOKE_LAUNCH_TIMEOUT_SECONDS", "120"))
    launch_env = {
        **os.environ,
        "RUN_VL_HYBRID_RUNTIME_TIMEOUT_SECONDS": str(launch_timeout_seconds),
    }
    try:
        launch = subprocess.run(
            launch_command,
            cwd=cwd,
            env=launch_env,
            text=True,
            capture_output=True,
            check=False,
            timeout=launch_timeout_seconds + 5,
        )
    except subprocess.TimeoutExpired as exc:
        timeout_stdout = exc.stdout or ""
        timeout_stderr = exc.stderr or ""
        if isinstance(timeout_stdout, bytes):
            timeout_stdout = timeout_stdout.decode(errors="replace")
        if isinstance(timeout_stderr, bytes):
            timeout_stderr = timeout_stderr.decode(errors="replace")
        result.update(
            {
                "launch_command": launch_command,
                "launch_status": "timeout",
                "launch_timeout_seconds": launch_timeout_seconds,
                "runtime_summary": _parse_runtime_summary(timeout_stdout),
                "status": "gpu_kernel_launch_timeout",
                "launch_tail": _sanitize_output(
                    "\n".join((timeout_stderr + timeout_stdout).splitlines()[-20:]),
                    cwd,
                ),
            }
        )
        return result
    runtime_summary = _parse_runtime_summary(launch.stdout)
    launch_timed_out = (
        launch.returncode == 124
        and "hybrid runtime timed out after" in (launch.stderr + launch.stdout)
    )
    result.update(
        {
            "launch_command": launch_command,
            "launch_returncode": launch.returncode,
            "launch_status": "passed" if launch.returncode == 0 else ("timeout" if launch_timed_out else "failed"),
            "launch_timeout_seconds": launch_timeout_seconds if launch_timed_out else None,
            "runtime_summary": runtime_summary,
            "status": (
                "gpu_kernel_launch_smoke_passed"
                if launch.returncode == 0
                else ("gpu_kernel_launch_timeout" if launch_timed_out else "gpu_kernel_launch_failed")
            ),
        }
    )
    if launch.returncode != 0:
        result["launch_tail"] = _sanitize_output("\n".join((launch.stderr + launch.stdout).splitlines()[-20:]), cwd)
    return result


